import{f as o,o as a,c,a2 as s}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"02 — Facturación masiva y comprobantes","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/02-facturacion-masiva-y-comprobantes.md","filePath":"relevamiento/reglas-negocio/02-facturacion-masiva-y-comprobantes.md","lastUpdated":null}'),t={name:"relevamiento/reglas-negocio/02-facturacion-masiva-y-comprobantes.md"};function r(n,e,d,i,l,u){return a(),c("div",null,[...e[0]||(e[0]=[s(`<h1 id="_02-—-facturacion-masiva-y-comprobantes" tabindex="-1">02 — Facturación masiva y comprobantes <a class="header-anchor" href="#_02-—-facturacion-masiva-y-comprobantes" aria-label="Permalink to &quot;02 — Facturación masiva y comprobantes&quot;">​</a></h1><p>Reglas extraídas del código descompilado de Procoop (<code>binarios/decompilado/ReglasNegocio/</code>). Las citas usan el formato <code>Archivo.cs:línea</code> relativo a la carpeta del namespace indicado. Todo lo que sigue es descripción en prosa y pseudocódigo propio; no es copia del código.</p><p>Fuera de alcance de este documento (se documentan en otros):</p><ul><li>Cálculo de los ítems de cada servicio (cargo fijo, tramos, prorrateo, cargos adicionales, fórmulas, anticipos y redondeo): ver <a href="./01-calculo-factura-servicios">01 — Cálculo de la factura de servicios</a>. Acá solo se indica <em>dónde</em> el proceso masivo llama a <code>clsFacturacionServicio</code>.</li><li>CAE/CAEA, WSFE, CESP, libro IVA y regímenes AFIP/ARCA: ver <a href="./03-afip-facturacion-electronica-e-iva">03 — AFIP, facturación electrónica e IVA</a>. Acá solo se describe cómo la numeración marca los comprobantes como &quot;bloqueados a la espera de CAE&quot;.</li><li>Intereses por mora y notificaciones: ver <a href="./04-mora-intereses-y-corte">04</a>. Lectura de códigos de barra en caja y entes recaudadores: ver <a href="./05-cobranzas-cajas-y-entes-recaudadores">05</a>. Catálogo completo de parámetros: ver <a href="./09-parametros-y-configuracion">09</a>.</li></ul><p>Namespace principal: <code>ReglasNegocio.Facturacion</code>. Tablas principales: <code>FACTURAS</code>, <code>ITEMSFAC</code>, <code>FACTMES</code> (+ <code>FACTMES_COMP</code>, <code>FACTMES_CTAS</code>, <code>SFACTME</code>), <code>COMPROB</code>, <code>COMPPOS</code>, <code>PTOVENTA</code>, <code>TIPO_FAC</code> (+ <code>PARSERFA</code>), <code>GRUPOS_FACTURA</code>, <code>SITIVA</code>, <code>HISBLOQ</code>, <code>CAUBLOQ</code>, <code>ANUFAC</code>/<code>ANUITEMSFAC</code>, <code>RELACION_COMP</code>, <code>TALONFAC</code>, <code>PAGOS360*</code>, <code>PRCAGAS</code>, <code>DEUDAVTA</code>.</p><hr><h2 id="_1-conceptos-y-vocabulario" tabindex="-1">1. Conceptos y vocabulario <a class="header-anchor" href="#_1-conceptos-y-vocabulario" aria-label="Permalink to &quot;1. Conceptos y vocabulario&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Término Procoop</th><th>Qué es</th><th>Tabla</th></tr></thead><tbody><tr><td>Cuenta / suministro</td><td>Unidad facturable de un titular (<code>COD_SUM</code>)</td><td><code>SUMSOC</code></td></tr><tr><td>Servicio de la cuenta</td><td>Instancia de un servicio en una cuenta (<code>ID_SERSOC</code>), con medidor, categoría, <code>ULT_FAC</code> (último período facturado), <code>SEC_PER</code> (secuencia), <code>CNT_FAC</code></td><td><code>SERSOC</code></td></tr><tr><td>Comprobante</td><td>Tipo legal/interno (factura A/B/C, ND, NC, LSP, interno…), con <code>DEB_CRE</code> (1 débito, 2 crédito), <code>RELACION</code> (comparte numeración con otro), <code>COD_COM_ANU</code> (comprobante que lo revierte), <code>NUM_MANUAL</code>, <code>INTERNO</code>, <code>TIPO_SIT</code>, <code>COPIAS</code></td><td><code>COMPROB</code></td></tr><tr><td>Punto de venta / sucursal</td><td><code>SUC_COM</code></td><td><code>PTOVENTA</code></td></tr><tr><td>Numerador</td><td>Último número por (comprobante, punto de venta), con flags <code>CAE</code>, <code>CAEA</code>, <code>CAI</code></td><td><code>COMPPOS</code></td></tr><tr><td>&quot;Tipo de factura&quot; / &quot;tipo de cuota&quot;</td><td>Clasificación comercial (<code>COD_TIP</code>, p. ej. &quot;EN&quot;, &quot;FN&quot;, &quot;SG&quot;), que además guarda <strong>la configuración de la facturación masiva</strong> (servicios, filtros, vencimientos, orden)</td><td><code>TIPO_FAC</code></td></tr><tr><td>Grupo de factura</td><td>Permite partir la factura de una cuenta en varias (por servicio/cuota), forzar tipo de factura o forzar Nota de Débito</td><td><code>GRUPOS_FACTURA</code></td></tr><tr><td>Log de facturación</td><td>Una corrida masiva, con sus servicios, cuentas y rangos de numeración emitidos</td><td><code>FACTMES</code>, <code>SFACTME</code>, <code>FACTMES_CTAS</code>, <code>FACTMES_COMP</code></td></tr><tr><td>Factura bloqueada</td><td><code>FACTURAS.ID_BLO</code> no nulo. Valor <code>-1</code> = pendiente de CAE. Otro valor = causa de bloqueo de cobro (<code>CAUBLOQ</code>)</td><td><code>FACTURAS</code>, <code>HISBLOQ</code></td></tr></tbody></table><p>Una factura tiene hasta <strong>4 vencimientos</strong> (<code>VTO1..VTO4</code>) con sus importes (<code>TOTAL1..TOTAL4</code>) más un <strong>próximo vencimiento</strong> (<code>PROX_VTO</code>, fecha estimada de la siguiente factura, que se imprime). <code>SALDO</code> arranca igual a <code>TOTAL1</code>.</p><hr><h2 id="_2-facturacion-masiva-mensual" tabindex="-1">2. Facturación masiva mensual <a class="header-anchor" href="#_2-facturacion-masiva-mensual" aria-label="Permalink to &quot;2. Facturación masiva mensual&quot;">​</a></h2><p>Clases: <code>clsFacturacionMasiva</code> (motor) y <code>clsDatosFacturacion</code> (parámetros de la corrida). La UI (no relevada acá) arma un <code>clsDatosFacturacion</code>, lo valida y dispara el proceso.</p><h3 id="_2-1-configuracion-el-tipo-de-factura-como-plantilla" tabindex="-1">2.1 Configuración: el &quot;tipo de factura&quot; como plantilla <a class="header-anchor" href="#_2-1-configuracion-el-tipo-de-factura-como-plantilla" aria-label="Permalink to &quot;2.1 Configuración: el &quot;tipo de factura&quot; como plantilla&quot;">​</a></h3><p>La configuración de una corrida se persiste <strong>en el registro <code>TIPO_FAC</code></strong> elegido, no en una tabla aparte:</p><ul><li><code>CargarConfiguracion(CodTpfc)</code> (<code>clsDatosFacturacion.cs:450-493</code>) lee de <code>TIPO_FAC</code>: servicios a facturar (<code>PARSERFA</code>), fechas de toma de estado desde/hasta (<code>FECD_ESTADO</code>, <code>FECH_ESTADO</code>), filtros de cuentas (<code>FILTRACUENTAS</code>, <code>FEC_ALTAS</code>, <code>ZONA</code>, <code>SECTOR</code>, <code>CONJUNTO</code>, <code>ZONAS_POSTALES</code>, <code>EMP_POSTAL</code>, <code>LOC_POSTAL</code>, <code>COD_CATSER</code>), <code>NOCOBRAENVIO</code>, si factura cuotas (<code>FACTURACUOTAS</code>, <code>TIPOCUOTA</code>, <code>FECDCUOTAS</code>, <code>FECHCUOTAS</code>, <code>INTDIFERIDOS</code>), si toma período por tipo (<code>PERIODOSXTIPO</code>), los 4 vencimientos y el próximo (<code>VTO1..VTO4</code>, <code>PROXVTO</code>), el tipo de factura a emitir (<code>TIPOFACTURA</code>, por defecto el propio <code>COD_TIP</code>) y el orden (<code>ORDEN</code>, por defecto alfabético).</li><li>Las fechas se guardan <strong>como texto</strong> (<code>strFechaVto1</code>, <code>strAltasAnterioresA</code>…) y se resuelven con <code>Nucleo.GetFechaDinamica</code> (expresiones relativas tipo &quot;fin de mes + 10&quot;); ver <code>CargarConfiguracionPrepaga</code> (<code>clsDatosFacturacion.cs:509-514</code>).</li><li><code>GuardarConfiguracion</code> (<code>clsDatosFacturacion.cs:538-585</code>) escribe de vuelta todo eso en <code>TIPO_FAC</code> y sincroniza <code>PARSERFA</code> (borra servicios deseleccionados, agrega los nuevos).</li><li><code>Cargar()</code> (<code>clsDatosFacturacion.cs:587-613</code>) arma la lista de servicios con <code>EsMedido = TIP_REG &amp;lt;= 3</code> y <code>FacturarConOtros = FAC_OTR == 1</code>.</li></ul><p>Parámetros de una corrida (<code>clsDatosFacturacion.cs:129-271</code>), resumidos:</p><ul><li><strong>A quién</strong>: <code>FacturarA</code> ∈ {Todas las cuentas, Una cuenta, Varias cuentas, Cuentas de control} (<code>clsDatosFacturacion.cs:12-18</code>). &quot;Varias cuentas&quot; se puede cargar desde Excel con una columna <code>Cod_Sum</code> (<code>clsFacturacionMasiva.ImportarCuentas</code>, <code>clsFacturacionMasiva.cs:253-273</code>).</li><li><strong>Qué</strong>: lista de servicios con período por servicio (<code>ServiciosFacturar.Periodo</code>) y, para medidos, rango de fechas de lectura a tomar (<code>ConsumoDesde/Hasta</code>); opcionalmente cuotas de ventas (<code>FacturarCuotas</code>) por rango de vencimiento o por lista explícita (<code>lstCuotas</code>).</li><li><strong>Período general</strong> (<code>PeriodoGeneral</code>, mes/año) y <strong>secuencia</strong> (<code>Secuencia</code>, para facturar más de una vez el mismo período, p. ej. bimestral partido).</li><li><strong>Tipo de comprobante</strong> (<code>TipoComprobante</code> = <code>COD_TPFC</code>) y <strong>tipo de factura</strong> (<code>TipoFactura</code> = <code>COD_TIP</code>).</li><li><strong>Vencimientos</strong> <code>FechaVto1..4</code> y <code>ProximoVto</code>.</li><li><strong>Orden de emisión</strong>: por cuenta, alfabético, o por zona/sector/recorrido postal (<code>OrdenarCuentas</code>, <code>clsFacturacionMasiva.cs:1914-1924</code>). El orden importa porque define el orden de numeración.</li><li><strong>Opcionales</strong>: <code>ForzarCuadro</code> (cuadro tarifario histórico, con <code>FechaVigenciaCuadro</code>), <code>NoAplicarAnticipos</code>, <code>NoFacturaEnvio</code> (no cobra franqueo), <code>Forzar_CodCom/SucCom/NumCom</code> (numeración manual, solo para un comprobante), <code>Simulacion</code>, <code>NoGenerarLog</code>.</li></ul><h3 id="_2-2-validaciones-previas" tabindex="-1">2.2 Validaciones previas <a class="header-anchor" href="#_2-2-validaciones-previas" aria-label="Permalink to &quot;2.2 Validaciones previas&quot;">​</a></h3><p><strong>De configuración</strong> — <code>clsDatosFacturacion.ValidarConfiguracion</code> (<code>clsDatosFacturacion.cs:278-403</code>):</p><ol><li>&quot;Una cuenta&quot; exige cuenta; &quot;Varias cuentas&quot; exige al menos una.</li><li>Período general no anterior a 5 años; <code>PeriodoDesde &amp;lt;= PeriodoHasta</code>.</li><li>Debe haber servicios seleccionados o cuotas; cada servicio seleccionado necesita período; cada servicio medido necesita rango de lecturas.</li><li>Si factura cuotas sin lista explícita, exige rango de fechas de cuotas.</li><li>Exige tipo de factura.</li><li>Ningún vencimiento anterior a hoy; <code>Vto1 &amp;lt;= Vto2 &amp;lt;= Vto3 &amp;lt;= Vto4</code>; <code>ProximoVto &gt; Vto4</code>.</li><li>Los 4 vencimientos y el próximo deben ser <strong>día hábil</strong> (<code>Nucleo.EsDomingo_O_Feriado</code>).</li><li>Si <code>Vto4 − Vto1 &gt; 60</code> días, ningún intervalo entre vencimientos consecutivos puede superar 60 días (<code>clsDatosFacturacion.cs:372-389</code>). Nota: si el total es ≤ 60 no se valida nada.</li><li>El submódulo Facturación no debe estar cerrado a la fecha mínima entre hoy y los vencimientos (<code>Nucleo.ModuloCerrado</code>, <code>clsDatosFacturacion.cs:390-401</code>).</li></ol><p><strong>De datos</strong> — <code>clsFacturacionMasiva.ValidarDatos</code> (<code>clsFacturacionMasiva.cs:503-532</code>):</p><ol><li>Valida que estén configuradas las variables 607, 2089, 311, 307, 2247 y 543 (<code>Nucleo.Valida_V2</code>). Por el uso en otras clases, 2089 es el concepto de interés y 607/311/307/2247/543 son conceptos o cuentas necesarias para la factura (ver doc 09 para el detalle).</li><li>Para <strong>cada situación de IVA</strong> (<code>SITIVA</code>) debe poder resolverse un comprobante de débito y uno de crédito para los servicios elegidos (<code>GetComprobanteOperacion</code> con importe +1 y −1); si no, &quot;Verifique el tipo de comprobante a generar para la Situación Fiscal X&quot;.</li><li>Si se forzó numeración, el número no debe existir ya en <code>FACTURAS</code>.</li></ol><p><strong>Fiscales y de estado</strong> (las llama la UI antes de iniciar):</p><ul><li><code>ValidarCESP</code> (<code>clsFacturacionMasiva.cs:275-288</code>): si algún servicio a facturar liquida como servicio público ante AFIP (<code>SERVICIO.LIQ_AFIP == 1</code>), debe existir un CESP vigente hoy en <code>CESPAFIP</code>. El usuario <code>SysAdmin</code> saltea la validación.</li><li><code>ValidarLUA</code> (<code>clsFacturacionMasiva.cs:290-298</code>): debe existir un registro vigente en <code>IIBB_LUA</code> (padrón de Ingresos Brutos). SysAdmin la saltea.</li><li><code>ValidarElectronicas</code> (<code>clsFacturacionMasiva.cs:300-308</code>): devuelve <em>true</em> (hay problema) si existen facturas con <code>ID_BLO = -1</code> (pendientes de CAE) emitidas hace 3 días o más. Es una advertencia para no apilar facturas sin autorizar.</li><li><code>IniciarProceso_Th</code> (<code>clsFacturacionMasiva.cs:320-357</code>) rechaza el arranque si hay una registración de capital social en curso (<code>clsSocios_Capital.registracionCapitalEnProceso</code>).</li><li><code>GenerarLog</code> (<code>clsDatosFacturacion.cs:615-684</code>) <strong>bloquea la tabla <code>FACTMES</code></strong>; si no puede, &quot;Verifique si otro usuario está corriendo el proceso&quot;. Es el semáforo que impide dos corridas reales simultáneas.</li></ul><h3 id="_2-3-seleccion-de-cuentas" tabindex="-1">2.3 Selección de cuentas <a class="header-anchor" href="#_2-3-seleccion-de-cuentas" aria-label="Permalink to &quot;2.3 Selección de cuentas&quot;">​</a></h3><p><code>GetIQSumsoc</code> (<code>clsFacturacionMasiva.cs:1854-1907</code>) arma la consulta base:</p><ol><li>Excluye cuentas cuyo último registro en <code>SUMNOFAC</code> (&quot;no facturar&quot;) está activo.</li><li>Según <code>FacturarA</code>: <ul><li>Todas: si <code>FiltraCuentas</code>, aplica conjunto (<code>COD_CNJ</code>), zonas postales (<code>ZON_FAC</code>), empresa postal (<code>COD_EPO</code>), localidad postal, zona/sector de lectura del servicio y lista de categorías (solo servicios conectados, <code>CONDICION</code> 2 o 3).</li><li>Una / Varias / Control: filtra por las cuentas indicadas.</li></ul></li><li>Se queda con cuentas que tengan <strong>algún servicio seleccionado, no marcado <code>NOFACTURAR</code> y no dado de baja (<code>CONDICION 4</code>) hace más de 6 meses respecto del período</strong>, o que tengan <strong>cuotas pendientes</strong> de facturar.</li></ol><p>Luego, por lote, <code>CargarServicios</code> (<code>clsFacturacionMasiva.cs:1751-1812</code>) decide qué servicios de esas cuentas entran:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>para cada SERSOC de la cuenta, de un servicio seleccionado y no NOFACTURAR:</span></span>
<span class="line"><span>    entra si: está conectado (CONDICION 2 o 3)</span></span>
<span class="line"><span>           o tiene consumos sin facturar (salvo servicios cotizados relacionados)</span></span>
<span class="line"><span>           o tiene cargos adicionales PRCAGAS pendientes del período (o sin período)</span></span>
<span class="line"><span>           o es baja con cobro proporcional de cargo fijo (COBRAR_CF_BAJA) dentro del período</span></span>
<span class="line"><span>    si es venta de prepaga: solo categorías prepagas en servicios medidos</span></span>
<span class="line"><span>    si FiltraCuentas y AltasAnterioresA: solo altas anteriores a esa fecha</span></span>
<span class="line"><span>    finalmente entra solo si:</span></span>
<span class="line"><span>        ULT_FAC &lt; período del servicio</span></span>
<span class="line"><span>        o (ULT_FAC == período y Secuencia != 0 ...)       -- refacturación por secuencia</span></span>
<span class="line"><span>        o tiene consumos pendientes o PRCAGAS pendientes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Es decir, <strong>la marca anti-doble-facturación es <code>SERSOC.ULT_FAC</code> + <code>SEC_PER</code></strong>: un servicio ya facturado en el período solo se vuelve a tomar con otra secuencia o si tiene consumos/cargos nuevos (<code>clsFacturacionMasiva.cs:1801-1805</code>). La anulación revierte esa marca (sección 7.3).</p><p><strong>Cuotas a facturar</strong> — <code>GetDeudaFacturar</code> (<code>clsFacturacionMasiva.cs:1814-1852</code>): cuotas de <code>DEUDAVTA</code> sin factura (<code>ID_FAC</code> nulo) ni estado A/F, y además:</p><ul><li>con lista explícita (<code>lstCuotas</code>): esas cuotas;</li><li>si no: cuotas normales (<code>TPCUOTA = 0</code>) con vencimiento hasta <code>FechaCuotasHasta</code> y no anteriores a <code>FechaCuotasDesde − 10 meses</code>, más intereses diferidos (<code>TPCUOTA = 1</code>) si se pidió; filtradas por los tipos de cuota configurados.</li></ul><p><strong>Muestra para control</strong> — <code>GetCuentasMuestra</code> (<code>clsFacturacionMasiva.cs:1680-1739</code>): elige al azar una cuenta por categoría, una por situación fiscal y una de &quot;grandes&quot; y otra de &quot;pequeños consumos&quot; (<code>CATE_SER.GC</code>), para simular antes de la corrida real (&quot;Cuentas de control&quot;).</p><h3 id="_2-4-simulacion" tabindex="-1">2.4 Simulación <a class="header-anchor" href="#_2-4-simulacion" aria-label="Permalink to &quot;2.4 Simulación&quot;">​</a></h3><p>La simulación usa el mismo motor (<code>GenerarFacturacion</code>) con <code>Simulacion = true</code>: no abre log, no numera, no ejecuta SQL; devuelve <code>lstFacturas</code> en memoria.</p><ul><li><code>SimularFacturas(IdsSersoc, IdTipoFac)</code> (<code>clsFacturacionMasiva.cs:413-456</code>): simula para servicios puntuales con configuración genérica (<code>CargarConfiguracionGenerica</code>: todo vence hoy, lecturas de los últimos 2 meses).</li><li><code>SimularFacturasConCuadros</code> (<code>clsFacturacionMasiva.cs:458-491</code>): simula una cuenta con un cuadro tarifario forzado (para comparar cuadros).</li><li><code>GenerarFacturaPrepaga</code> (<code>clsFacturacionMasiva.cs:359-411</code>): venta de energía prepaga. En modo real registra un consumo &quot;Venta de Prepaga&quot;, genera la factura y <strong>exige que el total coincida con el simulado</strong> (<code>clsFacturacionMasiva.cs:1367-1371</code>); si falla, elimina el consumo registrado.</li></ul><h3 id="_2-5-generacion-algoritmo-principal" tabindex="-1">2.5 Generación: algoritmo principal <a class="header-anchor" href="#_2-5-generacion-algoritmo-principal" aria-label="Permalink to &quot;2.5 Generación: algoritmo principal&quot;">​</a></h3><p><code>GenerarFacturacion</code> (<code>clsFacturacionMasiva.cs:543-745</code>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CargaInicial():</span></span>
<span class="line"><span>    si no es simulación ni NoGenerarLog: abre conexión de log y crea FACTMES (bloquea tabla)</span></span>
<span class="line"><span>    obtiene TODAS las cuentas ordenadas; cachea nombres, socios, personas, SITIVA,</span></span>
<span class="line"><span>    PTOVENTA, SERVICIO, CARGOS_ADICIONALES, CONCEPTOS_INT, GRUPOS_FACTURA</span></span>
<span class="line"><span>    crea clsFacturacionServicio (motor de ítems, doc 01) y, si corresponde, clsFacturacionCuotas</span></span>
<span class="line"><span>capitaliza = existen rubros de capital (RUBCAPI) y no V2(2736)</span></span>
<span class="line"><span>lote = V2_Decimal(2315) o 100</span></span>
<span class="line"><span>mientras queden cuentas:</span></span>
<span class="line"><span>    toma las próximas &lt;lote&gt; cuentas</span></span>
<span class="line"><span>    CargarServicios(lote)                                  -- sección 2.3</span></span>
<span class="line"><span>    para cada cuenta:</span></span>
<span class="line"><span>        items = GetItemsFactura(cuenta)                    -- servicios + cuotas</span></span>
<span class="line"><span>        si algún servicio dio error -&gt; a la lista de errores (la cuenta no se factura)</span></span>
<span class="line"><span>    facturas = ObtenerFacturas(items)                      -- arma comprobantes y numera</span></span>
<span class="line"><span>    si facturas == null -&gt; registra error y CORTA el proceso</span></span>
<span class="line"><span>    si no es simulación:</span></span>
<span class="line"><span>        EjecutarQuery()                                    -- persiste el lote</span></span>
<span class="line"><span>        si falla -&gt; CORTA el proceso</span></span>
<span class="line"><span>al final:</span></span>
<span class="line"><span>    si no se generó ninguna factura -&gt; rollback del log</span></span>
<span class="line"><span>    si real y V2(2769): asigna bloqueos de cobro automáticos (sección 6)</span></span>
<span class="line"><span>    si capitaliza y no V2(2855): registra capital social por factura</span></span>
<span class="line"><span>    cierra FACTMES (FIN = ahora) y commitea el log</span></span>
<span class="line"><span>    dispara evento _Finish con: correcta/no, mensaje, cuentas con error, cantidad bloqueadas</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p><code>GetItemsFactura</code> (<code>clsFacturacionMasiva.cs:977-994</code>) llama a <code>FacturarServicios</code> y luego a <code>FacturarCuotas</code>. Si la variable <strong>2443</strong> está activa y la cuenta no tiene ítems de servicio, no agrega cuotas (no emite factura solo de cuotas).</p><p><code>FacturarServicios</code> (<code>clsFacturacionMasiva.cs:996-1052</code>): recorre los servicios seleccionados ordenando primero los que <strong>no</strong> se facturan &quot;con otros&quot;. Un servicio marcado &quot;facturar con otros&quot; (<code>SERSOC.FCT_OTR</code>, o por defecto <code>SERVICIO.FAC_OTR</code>) <strong>solo se factura si la cuenta ya tiene ítems de otro servicio</strong> (no genera factura por sí solo). Para cada <code>SERSOC</code> pide ítems a <code>clsFacturacionServicio.GetItemsServicio(...)</code> con período, secuencia y rango de lecturas (doc 01). En venta de prepaga simulada usa <code>GetItemsServicioMedido</code> con el consumo comprado. Cualquier excepción queda como error de ese servicio.</p><p><code>FacturarCuotas</code> (<code>clsFacturacionMasiva.cs:1054-1127</code>): agrega las cuotas de la cuenta (<code>clsFacturacionCuotas.AgregarItemsCuotas</code>, <code>clsFacturacionCuotas.cs:376-404</code>) y las agrupa: las cuotas asociadas a un servicio van con ese servicio (y su grupo de factura); las de un tipo de cuota con <code>TIPO_FAC.GRUPOFAC</code> van al grupo indicado; el resto al grupo por defecto.</p><h3 id="_2-6-armado-de-comprobantes-obtenerfacturas" tabindex="-1">2.6 Armado de comprobantes (<code>ObtenerFacturas</code>) <a class="header-anchor" href="#_2-6-armado-de-comprobantes-obtenerfacturas" aria-label="Permalink to &quot;2.6 Armado de comprobantes (\`ObtenerFacturas\`)&quot;">​</a></h3><p><code>ObtenerFacturas</code> (<code>clsFacturacionMasiva.cs:1129-1517</code>), paso a paso:</p><ol><li><strong>Fórmulas de cargos adicionales no finales</strong>: resuelve en bloque las fórmulas de <code>CARGOS_ADICIONALES</code> para todos los servicios del lote (<code>clsEditorFormulas_Extensions.CargarFormulas</code>). El detalle está en el doc 01.</li><li><strong>Agrupa por (cuenta, grupo de factura)</strong> (<code>clsFacturacionMasiva.cs:1155-1157</code>). Cada grupo es una factura candidata. Los cargos que una fórmula manda a &quot;otro grupo&quot; se acumulan en <code>objOtro</code> y se agregan al cambiar de cuenta (<code>AgregarFactura</code>, <code>clsFacturacionMasiva.cs:1519-1579</code>): si ya existe una factura de esa cuenta para ese grupo o tipo se suman ahí; si no, se crea otra.</li><li><strong>Criterio de emisión</strong> (<code>clsFacturacionMasiva.cs:1230</code>): se emite la factura si algún ítem tiene importe ≠ 0, <strong>o</strong>, con la variable <strong>2526</strong>, si tiene consumos aunque el importe sea 0 (factura en cero por consumo), <strong>o</strong> (con <strong>3109</strong> y solo en simulación) si tiene importes.</li><li><code>AgregaFactura</code> (<code>clsFacturacionMasiva.cs:1603-1678</code>) crea la factura: <ul><li>Grupo 0 → toma el grupo cuyo <code>COD_TPFC</code> es el tipo de la corrida. Si el grupo tiene <code>FORZAR_ND</code>, el comprobante será Nota de Débito en vez de Factura.</li><li>Si el grupo tiene tipo de factura propio (<code>GRUPOS_FACTURA.COD_TPFC</code>), la factura toma ese tipo (salvo prepaga).</li><li>Período: el general, o el del tipo de factura si <code>TomarPeriodoXTipoDeFactura</code>.</li><li>Cabecera, ítems, impuestos y vencimientos los arma <code>clsFacturacionServicio.GetFactura(...)</code> (doc 01), recibiendo los 4 vencimientos y si se cobra envío.</li><li><strong>Comprobante</strong> por <code>clsComprobante.GetComprobanteOperacion</code> (sección 3.2) con el total.</li><li><strong>Total negativo</strong>: invierte signos de todos los ítems y cambia <code>Deb_Cre</code> (pasa a ser crédito) (<code>clsFacturacionMasiva.cs:1647-1651</code>).</li><li><strong>Punto de venta</strong>: el de prepaga del usuario si es venta de prepaga; si no, <code>GetPuntoVenta</code> (sección 4.2).</li></ul></li><li><strong>Cargos finales</strong>: si existen cargos adicionales marcados <code>FINAL</code> para el tipo (o en el cuadro histórico forzado), se resuelven fórmulas <em>sobre la factura ya armada</em> y se agregan ítems (<code>clsFacturacionMasiva.cs:1260-1322</code>).</li><li><strong>Generación distribuida / energía inyectada</strong> (<code>clsFacturacionMasiva.cs:1289-1297</code> y <code>1581-1601</code>): si la variable <strong>3094</strong> define un concepto, la factura da negativa y el servicio 1 tiene consumos de tipo de energía &quot;A&quot; donde lo inyectado supera lo consumido, en vez de emitir una nota de crédito se agrega un ítem &quot;Crédito por energía inyectada&quot; como <strong>anticipo a futuro</strong> (<code>FacturacionFutura</code>) que neutraliza el total.</li><li><strong>Anticipos y redondeo</strong>: <code>clsFacturacionServicio.AgregaAnticipoyRedondeo</code> (doc 01), salvo <code>NoAplicarAnticipos</code>.</li><li><strong>Total negativo después de cargos finales</strong>: busca el comprobante &quot;de anulación&quot; del actual (<code>COMPROB.COD_COM_ANU</code>, o el inverso), cambia el comprobante, invierte importes y <code>Deb_Cre</code> (<code>clsFacturacionMasiva.cs:1300-1317</code>).</li><li><strong>Prepaga</strong> (<code>clsFacturacionMasiva.cs:1340-1381</code>): redondeo especial (variable <strong>2342</strong>), recargo/bonificación por forma de pago; con <strong>2413</strong> el recargo neto va en una ND separada; si no, dentro de la factura. Valida total contra el simulado.</li><li><strong>Numeración y SQL</strong> (solo modo real, sección 4.3).</li></ol><h3 id="_2-7-persistencia-lotes-y-transacciones" tabindex="-1">2.7 Persistencia, lotes y transacciones <a class="header-anchor" href="#_2-7-persistencia-lotes-y-transacciones" aria-label="Permalink to &quot;2.7 Persistencia, lotes y transacciones&quot;">​</a></h3><p>No se usa el ORM para insertar facturas: cada factura se convierte en <strong>texto SQL</strong> (<code>clsComprobanteFactura.Get_Factura(..., GeneraQuery_Masiva: true)</code>), con <code>@IdFactura = @@IDENTITY</code> para encadenar ítems, observaciones, anticipos y actualizaciones de <code>CONS_SER</code>, <code>DEUDAVTA</code>, <code>PRCAGAS</code>, <code>INTERNAC</code> (<code>clsComprobanteFactura.cs:1156-1163</code>, <code>1208-1222</code>, <code>1321-1372</code>).</p><ul><li>Las queries se agrupan de a <strong>300 facturas</strong> por bloque (<code>clsFacturacionMasiva.cs:1486-1496</code>).</li><li>Cada bloque va envuelto en <code>BEGIN TRAN / TRY / COMMIT / CATCH ROLLBACK</code> y, ante error, ejecuta el SP <code>GrabarError</code> y <code>RAISERROR</code> (<code>InicioQuery</code>/<code>FinalQuery</code>, <code>clsFacturacionMasiva.cs:1741-1749</code>).</li><li><code>EjecutarQuery</code> (<code>clsFacturacionMasiva.cs:882-975</code>) ejecuta primero inserts/updates pendientes del contexto (en bloques de 1000 updates), después los bloques de facturas, todo dentro de una transacción por lote; al commitear, hace <code>SubmitChanges</code> de la <strong>conexión de numeración</strong> (que mantuvo bloqueados los registros de <code>COMPPOS</code>).</li><li>Hay <strong>tres conexiones</strong>: la de lectura/armado, la de numeración (<code>objConexionNumeracion</code>) y la del log (<code>objConexion_Log</code>, transacción abierta durante toda la corrida, que mantiene el bloqueo de <code>FACTMES</code>).</li></ul><p>Consecuencias importantes:</p><ul><li><strong>El commit es por lote</strong>: si falla el lote N, los lotes 1..N−1 quedan grabados y el proceso se detiene (<code>clsFacturacionMasiva.cs:623-637</code>). La corrida puede quedar parcial; el log igual se cierra si se generó al menos una factura.</li><li>El commit de facturas y el de numeración son dos commits distintos: si el segundo fallara, quedarían facturas grabadas con <code>COMPPOS</code> sin actualizar (<code>clsFacturacionMasiva.cs:957-973</code>).</li></ul><h3 id="_2-8-hilos-y-avance" tabindex="-1">2.8 Hilos y avance <a class="header-anchor" href="#_2-8-hilos-y-avance" aria-label="Permalink to &quot;2.8 Hilos y avance&quot;">​</a></h3><ul><li>La corrida real corre en <strong>un único hilo de fondo</strong> (<code>IniciarProceso_Th</code>, <code>clsFacturacionMasiva.cs:320-357</code>); no hay paralelismo entre lotes. El hilo replica el skin de DevExpress y activa/desactiva un timer en la ventana principal.</li><li>El avance se informa con eventos de <code>ClaseBase_WithProgressEvents</code>: mensajes por lote (&quot;Analizando Grupo n de m&quot;, &quot;Se generaron X facturas – Total general Y&quot;) y un máximo de pasos = cuentas × 2 + 50 % para la grabación (<code>clsFacturacionMasiva.cs:571-595</code>).</li><li><code>GetCantidadGrupos</code> (<code>clsFacturacionMasiva.cs:493-501</code>) estima la cantidad de lotes para la UI (usa redondeo bancario, mientras que el bucle usa techo: puede diferir en uno).</li><li>El evento <code>_Finish</code> devuelve una tabla de errores por servicio (servicio, cuenta, nombre, domicilio, medidor, error) (<code>clsFacturacionMasiva.cs:147-197</code>).</li></ul><h3 id="_2-9-log-de-la-corrida-y-cierre" tabindex="-1">2.9 Log de la corrida y cierre <a class="header-anchor" href="#_2-9-log-de-la-corrida-y-cierre" aria-label="Permalink to &quot;2.9 Log de la corrida y cierre&quot;">​</a></h3><p><code>FACTMES</code> guarda: período, secuencia, usuario, tipo, a quién se facturó, todos los filtros, cuotas, vencimientos, tipo de factura, orden, inicio y fin (<code>clsDatosFacturacion.cs:615-684</code>). Hijos:</p><ul><li><code>SFACTME</code>: servicio, período y rango de lecturas usados.</li><li><code>FACTMES_CTAS</code>: cuentas, cuando fue &quot;una&quot; o &quot;varias&quot;.</li><li><code>FACTMES_COMP</code>: <strong>rango de numeración emitido por comprobante y punto de venta</strong> (desde/hasta), más si requiere CAE. Se consulta con <code>GetComprobantesGenerados</code> (<code>clsDatosFacturacion.cs:702-715</code>).</li></ul><p><code>CargarCuentas</code>/<code>CargarServicios(FACTMES)</code> permiten re-cargar una corrida anterior (<code>clsDatosFacturacion.cs:717-743</code>). <code>GetFechaProximaFacturacion</code> propone la próxima fecha: último día del mes + 10, o un mes después de <code>TIPO_FAC.FECH_ULTFAC</code> si fue hace menos de 60 días (<code>clsDatosFacturacion.cs:686-700</code>).</p><p>Al cierre, si la variable <strong>2769</strong> está activa, se re-aplican bloqueos de cobro: para cada cuenta que tenga alguna factura bloqueada (causa ≠ −1), las facturas de hoy sin bloqueo reciben la causa mínima de esa cuenta (<code>clsFacturacionMasiva.cs:675-704</code>). Si hay rubros de capital y no está <strong>2855</strong>, se registra capital social sobre lo facturado (<code>clsFacturacionMasiva.cs:705-719</code>).</p><hr><h2 id="_3-tipos-de-comprobante-y-letras" tabindex="-1">3. Tipos de comprobante y letras <a class="header-anchor" href="#_3-tipos-de-comprobante-y-letras" aria-label="Permalink to &quot;3. Tipos de comprobante y letras&quot;">​</a></h2><h3 id="_3-1-modelo" tabindex="-1">3.1 Modelo <a class="header-anchor" href="#_3-1-modelo" aria-label="Permalink to &quot;3.1 Modelo&quot;">​</a></h3><ul><li><code>COMPROB</code> define cada comprobante; la letra (A/B/C/M) no es un campo lógico separado sino parte de cada código de comprobante (los códigos AFIP 1/2/3 = A, 6/7/8 = B, etc.), y <code>SITIVA</code> dice qué comprobante corresponde a cada situación de IVA.</li><li><code>TipoComprobante</code> (<code>TipoComprobante.cs</code>) <strong>no</strong> es la letra: es el tipo de documento identificado por un código de barras (Ninguno, Factura, Notificación, Talón, Entidad digital/Pagos360).</li><li><code>Comprobantes_Venta</code> (enum de núcleo): Factura, Nota de Débito, Nota de Crédito, Ticket fiscal.</li></ul><h3 id="_3-2-resolucion-del-comprobante-—-getcomprobanteoperacion" tabindex="-1">3.2 Resolución del comprobante — <code>GetComprobanteOperacion</code> <a class="header-anchor" href="#_3-2-resolucion-del-comprobante-—-getcomprobanteoperacion" aria-label="Permalink to &quot;3.2 Resolución del comprobante — \`GetComprobanteOperacion\`&quot;">​</a></h3><p><code>clsComprobante.cs:192-265</code>, con el importe redondeado a 2 decimales:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si algún servicio de la factura liquida como servicio público AFIP (LIQ_AFIP = 1):</span></span>
<span class="line"><span>    importe &lt; 0 -&gt; SITIVA.CSP_DEF  (crédito servicio público / LSP)</span></span>
<span class="line"><span>    si no       -&gt; SITIVA.SPU_DEF  (factura servicio público)</span></span>
<span class="line"><span>si algún servicio tiene comprobante propio (SERVICIO.COM_FAC si importe &gt; 0, COM_CRE si &lt; 0)</span></span>
<span class="line"><span>   y todos coinciden en uno solo -&gt; ese</span></span>
<span class="line"><span>si no:</span></span>
<span class="line"><span>    ajusta tipo: importe &lt; 0 y era Factura/ND -&gt; Nota de Crédito; importe &gt; 0 y era NC -&gt; Factura</span></span>
<span class="line"><span>    esMiPyME = cuenta MIPYME y |importe| &gt; |V2(2515)|  (umbral FCE MiPyME)</span></span>
<span class="line"><span>    Factura: TIPO_FAC.COD_COM si está; si no, MiPyME -&gt; COM_FAC_MIPYME; si no COM_DEF; si no 1</span></span>
<span class="line"><span>    NC:      MiPyME -&gt; COM_CRE_MIPYME; si no CRE_DEF; si no 5</span></span>
<span class="line"><span>    ND:      MiPyME -&gt; COM_DEB_MIPYME; si no DEB_DEF; si no 3</span></span>
<span class="line"><span>    Ticket:  SITIVA.COD_COM; si no 90</span></span>
<span class="line"><span>devuelve 0 si no pudo resolver (y ValidarDatos aborta)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>Otras funciones: <code>GetComprobanteDefault(Operaciones_default)</code> (comprobante por defecto de una operación, <code>COMPROB.OPE_DEFAULT</code>) y <code>GetComprobanteOperacion(Operaciones)</code> vía <code>OPE_COM</code> (<code>clsComprobante.cs:160-185</code>). <code>ValidarComprobanteSitIva</code> verifica que el comprobante elegido sea alguno de los configurados en la situación de IVA (<code>clsComprobanteFactura.cs:735-750</code>).</p><h3 id="_3-3-validaciones-de-un-comprobante-individual" tabindex="-1">3.3 Validaciones de un comprobante individual <a class="header-anchor" href="#_3-3-validaciones-de-un-comprobante-individual" aria-label="Permalink to &quot;3.3 Validaciones de un comprobante individual&quot;">​</a></h3><p><code>clsComprobanteBase.Validar</code> (<code>clsComprobanteBase.cs:222-226</code>): cuenta obligatoria, punto de venta ≠ 0 (salvo <strong>2549</strong>), número ≠ 0 si no es autonumérico, comprobante ≠ 0, año entre 1997 y 2050, al menos un ítem, ninguna cantidad 0, total no negativo.</p><p><code>clsComprobanteFactura.Validar</code> (<code>clsComprobanteFactura.cs:690-733</code>) agrega, en orden:</p><ol><li>Número manual no repetido.</li><li>Tipo de factura obligatorio.</li><li><code>Vto1</code> no anterior a hoy ni posterior a hoy + <strong>V2(2271)</strong> días.</li><li>Con <strong>739</strong>: un comprobante <code>INTERNO</code> no puede llevar conceptos gravados.</li><li><code>COMPROB.TIPO_SIT = 1</code> → solo para Responsables Inscriptos y Monotributistas; <code>TIPO_SIT = 2</code> → no válido para RI.</li><li>Un ítem de anticipo (producto subtipo 8) va solo, con el comprobante por defecto de &quot;débito anticipos de titulares&quot; y con producto exento.</li><li>Ninguna alícuota con base imponible negativa.</li><li>Módulo de facturación no cerrado a la fecha.</li><li>Comprobantes de crédito requieren el permiso <code>Generar_Creditos</code>.</li><li>Descuento exige concepto de descuento (<strong>2564</strong>).</li><li>Si el total supera <strong>V2(3080)</strong>, pregunta al usuario (es un <code>MessageBox</code> dentro de la capa de negocio).</li></ol><hr><h2 id="_4-numeracion-y-puntos-de-venta" tabindex="-1">4. Numeración y puntos de venta <a class="header-anchor" href="#_4-numeracion-y-puntos-de-venta" aria-label="Permalink to &quot;4. Numeración y puntos de venta&quot;">​</a></h2><h3 id="_4-1-numerador-comppos" tabindex="-1">4.1 Numerador <code>COMPPOS</code> <a class="header-anchor" href="#_4-1-numerador-comppos" aria-label="Permalink to &quot;4.1 Numerador \`COMPPOS\`&quot;">​</a></h3><ul><li>La clave es (comprobante, punto de venta). Si un comprobante tiene <code>COMPROB.RELACION</code>, <strong>usa la numeración del comprobante relacionado</strong> (por ejemplo FA y ND A comparten talonario) (<code>clsComprobante.cs:615-645</code>, <code>694-705</code>).</li><li><code>NuevoNumero</code> (<code>clsComprobante.cs:694-749</code>): abre transacción en la conexión de numeración, <strong>bloquea el registro de <code>COMPPOS</code></strong> (hasta 5 reintentos; luego &quot;Demasiados intentos de bloqueo… Se cerrará el sistema&quot;), incrementa <code>ULT_NUM</code> o lo fija al número forzado. Si no existe el numerador, bloquea la tabla y lo crea (y crea el <code>PTOVENTA</code> &quot;Automático&quot; si falta) (<code>clsComprobante.cs:473-488</code>, <code>562-587</code>).</li><li><code>GenerarComppos(SucCom)</code> crea en bloque los numeradores faltantes para un punto de venta (<code>clsComprobante.cs:589-608</code>).</li><li><code>ValidarNumcomEnFacturas</code> (<code>clsComprobante.cs:767-783</code>): si el número ya existe en <code>FACTURAS</code> (también para el comprobante relacionado), devuelve máximo + 1. Se usa para &quot;auto-reparar&quot; numeradores desfasados.</li></ul><h3 id="_4-2-punto-de-venta-—-getpuntoventa" tabindex="-1">4.2 Punto de venta — <code>GetPuntoVenta</code> <a class="header-anchor" href="#_4-2-punto-de-venta-—-getpuntoventa" aria-label="Permalink to &quot;4.2 Punto de venta — \`GetPuntoVenta\`&quot;">​</a></h3><p><code>clsComprobante.cs:443-471</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si V2(2549) y el comprobante tiene PTOVTA0 -&gt; 0</span></span>
<span class="line"><span>si algún servicio de la factura tiene punto de venta propio (SERVICIO.COD_POS):</span></span>
<span class="line"><span>    si todos coinciden -&gt; ese; si hay dos distintos -&gt; error &quot;2 o más servicios con puntos de venta diferentes&quot;</span></span>
<span class="line"><span>si el usuario tiene punto asignado -&gt; ese</span></span>
<span class="line"><span>si el equipo (PC) tiene punto -&gt; ese</span></span>
<span class="line"><span>si no -&gt; punto de venta de la empresa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-3-numeracion-en-la-masiva" tabindex="-1">4.3 Numeración en la masiva <a class="header-anchor" href="#_4-3-numeracion-en-la-masiva" aria-label="Permalink to &quot;4.3 Numeración en la masiva&quot;">​</a></h3><p><code>clsFacturacionMasiva.cs:1382-1515</code>. Para ser eficiente, no bloquea <code>COMPPOS</code> por cada factura:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>para cada factura del lote (en el orden de emisión):</span></span>
<span class="line"><span>    si hay numeración forzada: solo se permite si el lote generó 1 comprobante</span></span>
<span class="line"><span>    si no:</span></span>
<span class="line"><span>        clave = (comprobante de numeración = RELACION o el propio, punto de venta)</span></span>
<span class="line"><span>        si ya hay un rango abierto para la clave en FACTMES_COMP:</span></span>
<span class="line"><span>            número = hasta + 1   (en memoria)</span></span>
<span class="line"><span>            copia del rango los datos de CAE / CAI / tipo de autorización</span></span>
<span class="line"><span>        si no:</span></span>
<span class="line"><span>            número = NuevoNumero() (bloquea COMPPOS), verifica contra FACTURAS</span></span>
<span class="line"><span>            abre un rango FACTMES_COMP con desde = hasta = número</span></span>
<span class="line"><span>    si autorización CAE (tipo 2) y alguna alícuota tiene base negativa -&gt; aborta el lote</span></span>
<span class="line"><span>    genera el SQL de la factura; si queda con ID_BLO = -1 cuenta como &quot;bloqueada&quot;</span></span>
<span class="line"><span>al terminar el lote: fija COMPPOS.ULT_NUM = hasta de cada rango y guarda los rangos en el log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>La numeración es <strong>estrictamente secuencial dentro del lote, en el orden de cuentas elegido</strong>. Si el lote falla, la conexión de numeración hace rollback y los números no se consumen.</p><h3 id="_4-4-tipo-de-autorizacion-resultante" tabindex="-1">4.4 Tipo de autorización resultante <a class="header-anchor" href="#_4-4-tipo-de-autorizacion-resultante" aria-label="Permalink to &quot;4.4 Tipo de autorización resultante&quot;">​</a></h3><p>Al pedir número (<code>clsComprobante.cs:796-861</code>), según el numerador:</p><ul><li><code>COMPPOS.CAEA</code>: busca un CAEA vigente en <code>CESPAFIP</code> para la fecha; si hay, lo asigna (tipo CAEA). Si no hay y el numerador también es CAE, queda bloqueada. <ul><li><em>Corrección (segunda pasada)</em>: el filtro real del CAEA es <code>CAEA y FEC_INI &amp;lt;= Fecha &amp;lt;= FEC_FIN y VTO_CESP &amp;lt;= Hoy</code>, es decir, exige que el vencimiento del CAEA <strong>ya haya pasado o sea hoy</strong>. Es la condición inversa a la de la rama CESP, que pide <code>VTO_CESP &gt;= Hoy</code> (<code>clsComprobante.cs:822-837</code> contra <code>:850-860</code>). Puede ser un bug o una convención de carga de <code>CESPAFIP</code> <strong>[VERIFICAR]</strong>. Además, cuando no se encuentra CAEA y el numerador es CAE, la factura queda <code>Bloqueado</code> pero con <code>TipoAutorizacion</code> nulo (no se marca como CAE) (<code>clsComprobante.cs:833-836</code>).</li></ul></li><li><code>COMPPOS.CAE</code>: la factura nace <strong>bloqueada (<code>ID_BLO = -1</code>) esperando CAE</strong> (tipo CAE). La autorización posterior la documenta el doc 03.</li><li><code>COMPPOS.CAI</code>: asigna el CAI actual y su vencimiento (comprobante preimpreso/autoimpresor).</li><li>Comprobante de servicio público con CESP vigente: asigna el CESP (tipo CESP).</li></ul><p>En la masiva, si quedaron facturas bloqueadas por CAE se desactiva el envío automático <code>clsFacturacionElectronica.RegistrarFacturasAuto</code> para ese lote (<code>clsFacturacionMasiva.cs:884-887</code>).</p><hr><h2 id="_5-vencimientos" tabindex="-1">5. Vencimientos <a class="header-anchor" href="#_5-vencimientos" aria-label="Permalink to &quot;5. Vencimientos&quot;">​</a></h2><h3 id="_5-1-fechas" tabindex="-1">5.1 Fechas <a class="header-anchor" href="#_5-1-fechas" aria-label="Permalink to &quot;5.1 Fechas&quot;">​</a></h3><p>Las 4 fechas y el próximo vencimiento vienen de la configuración de la corrida (sección 2.2). En comprobantes sueltos (<code>RegistrarCabecera</code>, <code>clsComprobanteFactura.cs:2093-2133</code>) las cuatro fechas son hoy. <code>Guardar(cantidad)</code> permite emitir N comprobantes consecutivos sumando un mes a <code>Vto1</code> en cada uno (<code>clsComprobanteFactura.cs:757-778</code>).</p><h3 id="_5-2-importes-del-2o-3o-y-4o-vencimiento" tabindex="-1">5.2 Importes del 2º, 3º y 4º vencimiento <a class="header-anchor" href="#_5-2-importes-del-2o-3o-y-4o-vencimiento" aria-label="Permalink to &quot;5.2 Importes del 2º, 3º y 4º vencimiento&quot;">​</a></h3><p><code>CalcularVencimientos</code> (<code>clsComprobanteFactura.cs:618-623</code>): si un vencimiento no es posterior al anterior, repite el importe anterior; si no, llama a <code>Get_ImporteFactura</code> según el <strong>tipo de interés de la variable 74</strong> (<code>clsComprobanteFactura.cs:1771-1793</code>). La tasa o monto sale de la variable <strong>578</strong>; al recargo se le suma el IVA del concepto de interés <strong>606</strong> según la situación de IVA del titular (<code>CalcularIVA_Interes</code>, <code>clsComprobanteFactura.cs:1918-1927</code>).</p><table tabindex="0"><thead><tr><th>Modo (V2 74)</th><th>Regla (T = total, r = V2 578)</th><th>Cita</th></tr></thead><tbody><tr><td>Fijo en pesos</td><td>Vto2 = T + r; Vto3 = T + 2r; Vto4 = T + 3r (sin IVA)</td><td><code>:1826-1837</code></td></tr><tr><td>Fijo porcentaje</td><td>Vto2 = T·(1+r%) + IVA; Vto3 y Vto4 se capitalizan sobre el anterior</td><td><code>:1803-1824</code></td></tr><tr><td>Variable porcentaje</td><td>T + T·r%·(días entre Vto1 y el vto) + IVA</td><td><code>:1795-1801</code></td></tr><tr><td>Tramas por importe</td><td>Busca en <code>TRAMASREC</code> la trama cuyo rango de importe contiene T (por tipo de factura o genérica); recargo = T·valor%·días (o 1 si <code>TIPOVALOR = 1</code>) + IVA</td><td><code>:1839-1869</code></td></tr><tr><td>Trama por vencimiento</td><td>En <code>TRAMASREC</code>, la fila con rango 1–1 es para Vto2, 2–2 Vto3, 3–3 Vto4 (o la primera genérica); recargo = T·valor%·días + IVA</td><td><code>:1871-1916</code></td></tr></tbody></table><p>Regla de consistencia: al refrescar totales, si <code>Total2 &amp;lt; Total</code> se igualan los tres totales posteriores al total (<code>clsComprobanteFactura.cs:2164-2173</code>).</p><p>Redondeo: si <strong>V2(21)</strong> está desactivada (<code>RedondearTotal = true</code>), la fecha de emisión ≠ Vto1 y no es CAE, los 4 totales se redondean a 2 decimales (<code>clsComprobanteFactura.cs:610-613</code>, <code>797-804</code>).</p><p>En la masiva, los vencimientos y sus importes los calcula <code>clsFacturacionServicio.GetFactura</code> usando estas mismas reglas (doc 01).</p><hr><h2 id="_6-bloqueo-de-facturas" tabindex="-1">6. Bloqueo de facturas <a class="header-anchor" href="#_6-bloqueo-de-facturas" aria-label="Permalink to &quot;6. Bloqueo de facturas&quot;">​</a></h2><p>Hay dos usos de <code>FACTURAS.ID_BLO</code>:</p><ol><li><strong><code>-1</code> = pendiente de autorización electrónica</strong>. Lo asigna la numeración (sección 4.4). Ninguna operación manual de bloqueo lo pisa: los UPDATE filtran <code>isnull(ID_BLO,0) &amp;lt;&gt; -1</code> (<code>clsComprobanteFactura.cs:2565</code>) y la consulta de facturas bloqueables excluye las −1 (<code>:2480</code>).</li><li><strong>Causa de bloqueo de cobro</strong> (<code>CAUBLOQ</code>): una factura bloqueada no se cobra en caja (la regla de caja está en doc 05).</li></ol><p>Operaciones:</p><ul><li><code>Get_FacturasBloqueo(filtros)</code> (<code>clsComprobanteFactura.cs:2477-2530</code>): impagas (<code>PAGA = &#39;&#39;</code>), filtrables por cuenta, titular, tipo, emisión y vencimiento. DTO <code>FacturasBloqueadas</code> (<code>FacturasBloqueadas.cs</code>) y filtros <code>FiltrosFacturasBloquear</code> (<code>FiltrosFacturasBloquear.cs</code>).</li><li><code>Asignar_Bloqueo(ids, causa)</code> (<code>clsComprobanteFactura.cs:2538-2590</code>): UPDATE en bloques de 500 + <strong>historial <code>HISBLOQ</code></strong> (fecha, causa, usuario) por factura. Causa nula = desbloquear.</li><li><code>Asignar_Bloqueo_ConIntereses</code> (<code>clsComprobanteFactura.cs:2592-2635</code>): bloquea y, en la misma transacción, emite una factura de intereses (<code>clsRegistracionCobranza.Generar_Factura_X_Intereses</code>).</li><li><code>BloquearDesbloquearComprobantes</code> (<code>clsComprobanteFactura.cs:2135-2162</code>): alterna (si no tenía bloqueo, lo pone; si tenía, lo quita) desde la pantalla de cobranzas.</li><li>Propagación automática al cerrar la masiva con <strong>2769</strong> (sección 2.9).</li></ul><hr><h2 id="_7-anulacion-notas-de-credito-y-reversion" tabindex="-1">7. Anulación, notas de crédito y reversión <a class="header-anchor" href="#_7-anulacion-notas-de-credito-y-reversion" aria-label="Permalink to &quot;7. Anulación, notas de crédito y reversión&quot;">​</a></h2><p>Clase: <code>clsAnulacionFacturas</code>.</p><h3 id="_7-1-validaciones-validaranulacion-clsanulacionfacturas-cs-386-515" tabindex="-1">7.1 Validaciones (<code>ValidarAnulacion</code>, <code>clsAnulacionFacturas.cs:386-515</code>) <a class="header-anchor" href="#_7-1-validaciones-validaranulacion-clsanulacionfacturas-cs-386-515" aria-label="Permalink to &quot;7.1 Validaciones (\`ValidarAnulacion\`, \`clsAnulacionFacturas.cs:386-515\`)&quot;">​</a></h3><p>Para <strong>una</strong> factura:</p><ul><li>No anular algo ya anulado (<code>ESTADO = &#39;A&#39;</code>), salvo que se pida eliminar.</li><li>Eliminar no se permite si tiene pagos (<code>IT_PAGSO</code>) ni financiaciones (<code>IT_RECCO</code>).</li><li><strong>Autorizada en ARCA</strong> (<code>CAE</code> no vacío y <code>TP_CODIGO = 2</code>): no se puede eliminar; si se pide anular, avisa que <strong>se generará otro comprobante para revertirla</strong> y pide confirmación.</li><li>Incluida en una solicitud de cobro externa Pagos360: si el estado de la solicitud no es 0, 1 o 4, no se puede eliminar; si lo es, pide confirmación.</li></ul><p>Para <strong>varias</strong>:</p><ul><li>Las que tienen pagos se excluyen (con confirmación) y se listan en &quot;comprobantes excluidos&quot;.</li><li>Si alguna está autorizada en ARCA: error (no se anulan electrónicas en masa).</li><li>Pagos360 igual que arriba.</li></ul><p>Para todas:</p><ul><li>Las de fecha ≤ <strong>cierre del módulo Facturación</strong> se excluyen (una sola: error con la fecha de cierre).</li><li>Si hay facturas con <code>ID_BLO = -1</code> (esperando CAE): doble confirmación (&quot;esta operación no puede revertirse&quot;).</li><li>Las de venta de prepaga se excluyen en masa.</li><li><code>AnularFacturas</code> además filtra nuevamente sin pagos, posteriores al cierre y no prepaga (<code>clsAnulacionFacturas.cs:93-99</code>).</li></ul><p>Validaciones auxiliares: <code>ValidarCapitalizacionEnFacturas</code> (si tocan rubros de capital, <code>:366-384</code>), <code>ValidarCreditosGenerados</code> (una factura no puede revertirse dos veces: si en <code>RELACION_COMP</code> ya hay un comprobante de signo opuesto y mismo total, error, <code>:996-1061</code>), <code>ValidarCespLQSP</code> (para revertir servicios públicos debe haber CESP vigente, <code>:1063-1075</code>), <code>VerificarAnticipos</code> (un anticipo ya utilizado no se anula, <code>:685-693</code>).</p><h3 id="_7-2-anular-vs-revertir" tabindex="-1">7.2 Anular vs. revertir <a class="header-anchor" href="#_7-2-anular-vs-revertir" aria-label="Permalink to &quot;7.2 Anular vs. revertir&quot;">​</a></h3><p><code>FinalizarAnulacion</code> (<code>clsAnulacionFacturas.cs:695-768</code>) decide:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>siempre: libera lo que la factura consumió</span></span>
<span class="line"><span>    CONS_SER -&gt; sin factura, FACTURADO = &#39;&#39;   (los consumos de prepaga se borran)</span></span>
<span class="line"><span>    INTERNAC, LLA_CEL, PRCAGAS -&gt; sin factura</span></span>
<span class="line"><span>    DEUDAVTA -&gt; sin factura, estado &#39;&#39;        (las cuotas vuelven a quedar pendientes)</span></span>
<span class="line"><span>    PRESUPU -&gt; estado &#39;P&#39;</span></span>
<span class="line"><span>    ANTICIPOS -&gt; devuelve el saldo aplicado (ANTIFACTU)</span></span>
<span class="line"><span>    borra MOV_PRO de facturación, CAPITAL, FACTURAS_TERCEROS, TALONFAC, COMPNOTI,</span></span>
<span class="line"><span>          OB_FACT, ANTIFACTU, ANTICIPOS, FAC_EXTRAS</span></span>
<span class="line"><span>si PAGADO = 0 y (sin CAE o el punto de venta no es CAE o es prepaga):</span></span>
<span class="line"><span>    copia cabecera e ítems a ANUFAC / ANUITEMSFAC (auditoría, con usuario y fecha)</span></span>
<span class="line"><span>    borra ITEMSFAC</span></span>
<span class="line"><span>    si &quot;eliminar&quot;: borra RELACION_COMP, PAGOS360_ITEMS y la FACTURA</span></span>
<span class="line"><span>    si no: FACTURAS.ESTADO = &#39;A&#39; y todos los totales, saldo y anticipo en 0</span></span>
<span class="line"><span>si no (electrónica autorizada o con pagos):</span></span>
<span class="line"><span>    REVERTIR: emite un comprobante inverso (sección 7.4)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>Todo se arma como SQL por factura con su propio <code>BEGIN TRAN/TRY/CATCH</code> y se ejecuta en bloques de 500 (<code>clsAnulacionFacturas.cs:107-154</code>, <code>517-537</code>).</p><h3 id="_7-3-efectos-sobre-el-servicio-facturado" tabindex="-1">7.3 Efectos sobre el servicio facturado <a class="header-anchor" href="#_7-3-efectos-sobre-el-servicio-facturado" aria-label="Permalink to &quot;7.3 Efectos sobre el servicio facturado&quot;">​</a></h3><ul><li><code>AnularSersoc</code> (<code>clsAnulacionFacturas.cs:565-648</code>): por cada <code>SERSOC</code> facturado, <code>CNT_FAC − 1</code>; si queda en 0, limpia <code>ULT_FAC</code> y <code>SEC_PER</code>; si la factura era la última (mismo período y secuencia), <strong>retrocede la marca</strong>: con secuencia 2 → 1; con 1 → 2 y período − 1. Para obras (<code>TIP_CAL = 17</code>) descuenta cuotas pagas y unidades facturadas; para viviendas descuenta el porcentaje facturado según el precio vigente de <code>PRECIOSVIV</code>.</li><li><code>DevolverFranqueo</code> (<code>clsAnulacionFacturas.cs:539-563</code>): si la factura cobró franqueo (producto subtipo 17) y era el último envío registrado en la cuenta, retrocede <code>SUMSOC.SEC_EPO</code>/<code>PER_EPO</code>.</li><li><code>AnularRedondeo</code> (<code>clsAnulacionFacturas.cs:650-683</code>): devuelve al acumulador de redondeo de la cuenta (<code>DEUDARED</code>, o <code>DEUDARED_TIPO</code> por tipo de factura) lo que la factura había aplicado.</li></ul><h3 id="_7-4-comprobante-de-reversion-nc-nd" tabindex="-1">7.4 Comprobante de reversión (NC/ND) <a class="header-anchor" href="#_7-4-comprobante-de-reversion-nc-nd" aria-label="Permalink to &quot;7.4 Comprobante de reversión (NC/ND)&quot;">​</a></h3><p><code>CargarQueryRevertirFactura</code> (<code>clsAnulacionFacturas.cs:770-993</code>) elige el comprobante:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si es CVLP con número indicado -&gt; comprobante por defecto &quot;CVLP Débito&quot;</span></span>
<span class="line"><span>si se fuerza LSP              -&gt; SITIVA.CSP_DEF de la cuenta</span></span>
<span class="line"><span>si se fuerza electrónica      -&gt; SITIVA.CRE_DEF</span></span>
<span class="line"><span>si el comprobante tiene COD_COM_ANU -&gt; ese</span></span>
<span class="line"><span>si no, por la situación de IVA de la cuenta:</span></span>
<span class="line"><span>    era NC por defecto   -&gt; ND por defecto</span></span>
<span class="line"><span>    era crédito SP (CSP) -&gt; factura SP (SPU), y viceversa</span></span>
<span class="line"><span>    era factura o ND     -&gt; NC por defecto</span></span>
<span class="line"><span>si no resuelve -&gt; error</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>El comprobante nuevo es un <strong>clon de la factura</strong> con fecha hoy, vencimientos hoy (o los indicados), los 4 totales = <code>TOTAL1</code>, saldo pleno, impago, automático, número nuevo (o el CVLP indicado) e ítems copiados. Se vincula en <code>RELACION_COMP</code> (origen = factura anulada, generado = nueva). Las opciones (<code>OpcionesCreditosXComprobantes</code>, <code>clsAnulacionFacturas.cs:15-61</code>) permiten:</p><ul><li><strong>Revertir consumos</strong>: inserta un <code>CONS_SER</code> espejo con consumo negativo y estados invertidos (fechas de lectura opcionales). Con &quot;permitir volver a facturar&quot; inserta además una copia del consumo original <strong>sin facturar</strong>, para que la próxima masiva lo vuelva a tomar; si no, retrocede el estado de lectura del <code>SERSOC</code> (<code>clsAnulacionFacturas.cs:866-922</code>).</li><li><strong>Liberar créditos/débitos</strong>: devuelve anticipos y libera cuotas, cargos, internacionales y llamadas.</li><li><strong>Revertir stock</strong> de productos que llevan stock (entrada, salvo comprobantes 5, 6, 83 y 92).</li><li>&quot;Permitir volver a facturar&quot; también aplica <code>AnularSersoc</code> y <code>DevolverFranqueo</code>.</li></ul><p><code>CreditosporComprobantes</code> (<code>clsAnulacionFacturas.cs:231-318</code>) aplica esto en masa (bloques de 100) desde la pantalla &quot;créditos por comprobantes&quot;. Las fechas de vencimiento de la NC no pueden ser anteriores a hoy ni desordenadas (<code>Validar</code>, <code>:56-60</code>).</p><h3 id="_7-5-relacion-manual-entre-comprobantes" tabindex="-1">7.5 Relación manual entre comprobantes <a class="header-anchor" href="#_7-5-relacion-manual-entre-comprobantes" aria-label="Permalink to &quot;7.5 Relación manual entre comprobantes&quot;">​</a></h3><p><code>Get_Comprobantes(ID_FAC, días)</code> lista los comprobantes de la misma cuenta, no internos ni anulados, de los últimos N días, marcando los ya relacionados; <code>Guardar_RelacionComprobantes</code> graba o borra vínculos en <code>RELACION_COMP</code> con las marcas <code>ANULACION</code> e <code>INFORMAR_CUIT</code> (necesarias para informar comprobantes asociados a ARCA) (<code>clsComprobanteFactura.cs:2637-2764</code>).</p><hr><h2 id="_8-recategorizacion" tabindex="-1">8. Recategorización <a class="header-anchor" href="#_8-recategorizacion" aria-label="Permalink to &quot;8. Recategorización&quot;">​</a></h2><p>Clase: <code>clsRecategorizacion</code>. Cambia la categoría de servicios según consumo. Tres modos (<code>clsRecategorizacion.cs:17-54</code>):</p><ol><li><strong>Energía por porcentaje de ahorro</strong> (<code>Get_Recategorizacion_Energia</code>, <code>:214-272</code>): compara consumo del período actual contra un período de comparación (opcionalmente en consumo diario). <code>Ahorro = 100 − actual/anterior·100</code>. Si el ahorro es ≥ 0, la nueva categoría es la del mismo grupo (<code>COD_GRC</code>) cuyo rango <code>MIN_GRC..MAX_GRC</code> contiene el ahorro. Si es negativo (consumió más), se desplaza desde el mínimo de la categoría actual; si queda igual, no cambia.</li><li><strong>Energía por consumo total</strong> (<code>:274-307</code>): la categoría del mismo <code>GRUPO_CONSUMO</code> cuyo rango <code>MIN_GRUPO..MAX_GRUPO</code> contiene el consumo actual.</li><li><strong>Gas</strong>: <ul><li><strong>Últimos 6 / 12 períodos</strong> (<code>Get_Recategorizacion_Gas</code>, <code>:309-446</code>): suma los consumos de los últimos 12 períodos (o bimestres con <strong>2498</strong>, o por fecha de lectura con <strong>2530</strong>); en modo &quot;corregido&quot; aplica el factor calórico, presión y temperatura del período (<code>FACTOR_CAL</code>) vía <code>clsConsumos.CorregirConsumoGAS</code>; con &quot;proporcional 365&quot; lleva el consumo a un año. Elige la categoría del grupo con rango que lo contenga (con <strong>3184</strong>, ignora inactivas y ordena por <code>CATE_SER_EXTRAS.ORDEN</code>). Redondeo del consumo corregido según <strong>119</strong> (2 = truncar, 3 = redondear).</li><li><strong>Cambio de cuadro (beneficio por ahorro)</strong> (<code>Get_Recategorizacion_GasCuadros</code>, <code>:448-611</code>): exige que cada categoría ENARGAS tenga cuadros A, B, S y H. Compara contra el mismo período del año anterior (o, salvo variable <strong>2242</strong> = &quot;TEMP&quot;, contra el año anterior a ese si no hay datos). Regla: cuadro E se mantiene en E; beneficiarios con estado 67/70 → H si ahorró ≥ 20 %, si no S; resto → B si ahorró ≥ 20 %, si no A.</li></ul></li></ol><p>Filtros comunes: servicio, cuenta, grupo, zonas, categorías, solo prepagas y &quot;recategorización previa&quot; (nunca recategorizados / con menos de 6 períodos) (<code>:56-95</code>).</p><p><code>Confirmar_Recategorizacion</code> (<code>:641-712</code>): guarda la categoría anterior (<code>CAT_ANT</code>), la nueva (<code>COD_CAT</code>, <code>COD_CATSER</code>), la fecha; en gas además períodos, consumo, método (<code>CAL_CAT</code>) y <strong>estado de beneficio</strong> (<code>ESTBEN</code>: A→96, B→71, H→70, S→67 en la cooperativa &quot;ARR&quot; (V2 2264) o 98 en el resto, T→97, Z→95; para E solo actualiza <code>ESTBEN</code> a 68/69 según la categoría ENARGAS). Actualiza la categoría de los <strong>consumos aún no facturados</strong> y deja una <strong>nota en la cuenta</strong> (<code>NOTA_SUM</code>) con el motivo. Todo en un único SQL.</p><p><code>CorregirConsumos</code> (<code>:714-748</code>) re-corrige consumos de gas sin facturar con un factor base, excluyendo los consumos divididos automáticamente.</p><hr><h2 id="_9-retroactivos" tabindex="-1">9. Retroactivos <a class="header-anchor" href="#_9-retroactivos" aria-label="Permalink to &quot;9. Retroactivos&quot;">​</a></h2><p>Clase: <code>clsRetroactivos</code>. Genera <strong>cargos adicionales pendientes</strong> (<code>PRCAGAS</code>) para cobrar o devolver diferencias en la próxima facturación. Dos procesos (<code>TipoProceso</code>):</p><ul><li><strong>0 – sobre consumos facturados</strong> (<code>GetItemsModificar</code>, <code>clsRetroactivos.cs:336-434</code>): toma <code>CONS_SER</code> facturados del servicio en el período (y opcionalmente el anterior), con filtros de conceptos de consumo, cuenta, zona, bajas y categorías (actual de la lectura, actual del servicio, o cambio desde categorías anteriores). Agrupa por servicio y calcula: <ul><li>cantidad = consumo, o el tramo <code>TramaDesde..TramaHasta</code> del consumo, por una proporción;</li><li>precio unitario = importe fijo, o porcentaje de lo facturado del servicio, o <strong>proporcional por días</strong> entre la fecha de lectura y una fecha de corte (<code>ImporteProporcional / días de lectura × días afectados</code>).</li></ul></li><li><strong>1 – sobre conceptos facturados</strong> (<code>:436-506</code>): toma ítems de facturas del rango de fechas con un concepto o impuesto base, y aplica importe fijo o porcentaje de lo facturado.</li></ul><p>Interés opcional: <code>Total × días entre emisión y la próxima facturación × tasa / −100</code> (<code>:429-432</code>, <code>:501-504</code>). El signo negativo hace que el interés reste (ver &quot;Dudas abiertas&quot;).</p><p>Validaciones (<code>ValidarPropiedades</code>, <code>:144-234</code>): concepto a facturar obligatorio; importe o porcentaje (o proporcional); proporción ≠ 0 si no hay importe; rangos de consumo y de trama coherentes; servicio obligatorio; concepto base en proceso 1; si hay interés, próxima facturación, tasa y concepto; filtro de categorías obligatorio.</p><p><code>ValidarRetroactivosyaCreados</code> (<code>:509-520</code>) impide duplicar: si ya existe un <code>PRCAGAS</code> pendiente con el mismo período base, tramas, concepto y rangos para alguna de las cuentas, falla. <code>RealizarCambios</code> (<code>:522-583</code>) inserta los <code>PRCAGAS</code> (con el comprobante de origen, período base <code>PERIODOB</code>, tramas y tipo de factura) y, si corresponde, uno extra por el interés. La masiva los levanta como cargos pendientes (sección 2.3).</p><hr><h2 id="_10-modificacion-masiva" tabindex="-1">10. Modificación masiva <a class="header-anchor" href="#_10-modificacion-masiva" aria-label="Permalink to &quot;10. Modificación masiva&quot;">​</a></h2><h3 id="_10-1-facturas-emitidas-clsmodificacionfacturas" tabindex="-1">10.1 Facturas emitidas (<code>clsModificacionFacturas</code>) <a class="header-anchor" href="#_10-1-facturas-emitidas-clsmodificacionfacturas" aria-label="Permalink to &quot;10.1 Facturas emitidas (\`clsModificacionFacturas\`)&quot;">​</a></h3><p>Modificaciones posibles (<code>clsModificacionFacturas.cs:15-31</code>): todos los vencimientos, uno de ellos, fecha de emisión, próximo vencimiento, o importes de los vencimientos 2–4.</p><ul><li>Fecha nueva = fecha fija, o fecha original + N días, opcionalmente desplazada al siguiente día hábil (<code>Resultados.GetFecha</code>, <code>:229-244</code>). No se puede indicar fecha fija y días a la vez (<code>:95-101</code>).</li><li>Importes 2–4 = <code>TOTAL1 + valor</code> (modo 1) o <code>TOTAL1 × valor</code> (otro modo) (<code>:227</code>).</li><li>Filtros: cuentas, titulares, zona/sector de lectura, zona postal, referencia, comprobante, punto de venta, período, emisión, solo mensuales (<code>FECHA &amp;lt;&gt; VTO1</code>), rango de números, tipo, servicio/categoría, clase, solo débito automático, conjunto, ocupación, solo impagas (<code>:247-357</code>).</li><li><strong>Siempre</strong> excluye facturas anteriores al cierre de Facturación; además excluye las de emisión ≤ máximo entre <strong>V2(67)</strong> (cierre de ventas) y <strong>V2(2528)</strong> (<code>validarFacturas</code>, <code>:386-427</code>). La fecha de emisión nueva tampoco puede ser ≤ cierre de ventas (<code>:102-106</code>).</li><li>Si hay <strong>facturas electrónicas</strong>, pregunta si incluirlas advirtiendo problemas con ARCA; si no, las excluye (<code>:351-356</code>).</li><li><code>RegistrarCambios</code> (<code>:538-607</code>) registra <strong>auditoría</strong> por factura y hace un UPDATE masivo solo de <code>TOTAL2..4</code>, <code>VTO1..4</code>, <code>PROX_VTO</code> y <code>FECHA</code>.</li></ul><h3 id="_10-2-cuotas-de-ventas-clsmodificacioncuotas" tabindex="-1">10.2 Cuotas de ventas (<code>clsModificacionCuotas</code>) <a class="header-anchor" href="#_10-2-cuotas-de-ventas-clsmodificacioncuotas" aria-label="Permalink to &quot;10.2 Cuotas de ventas (\`clsModificacionCuotas\`)&quot;">​</a></h3><p>Sobre cuotas pendientes de <code>DEUDAVTA</code> (sin factura, no anuladas ni facturadas) (<code>clsModificacionCuotas.cs:387-450</code>):</p><ul><li><strong>Importe de un producto</strong> por porcentaje: reparte el ajuste proporcional a capital entre las cuotas, actualiza el ítem de la venta (<code>IT_COMPV</code>), los totales del comprobante de venta y el IVA de cada cuota (<code>IVAVTA</code>).</li><li><strong>Costo del producto</strong>: igual, pero el porcentaje es la diferencia entre el precio actual del producto y el último precio usado (<code>ULT_PRE_VSI</code>), y actualiza ese último precio.</li><li><strong>Desplazar vencimientos</strong> N meses.</li><li><strong>Cambio de tasa de IVA</strong> general y/o sobretasa, recalculando el IVA de la cuota y opcionalmente el del interés (concepto <strong>2089</strong>).</li><li><strong>Tipo de cuota</strong>; también sobre facturas de financiación ya emitidas (<code>CLASE = 1</code>), incluyendo pagos registrados.</li><li>Filtro por prepagas (todas / excluir / solo).</li></ul><p><code>RegistrarCambios</code> (<code>:597-957</code>) deja una <code>NOTA_SUM</code> por comprobante y, si cambió el capital, inserta un movimiento <code>CAPITAL</code> de ajuste. Todo en una transacción.</p><hr><h2 id="_11-facturacion-de-cuotas-y-de-terceros" tabindex="-1">11. Facturación de cuotas y de terceros <a class="header-anchor" href="#_11-facturacion-de-cuotas-y-de-terceros" aria-label="Permalink to &quot;11. Facturación de cuotas y de terceros&quot;">​</a></h2><h3 id="_11-1-cuotas-de-ventas-dentro-de-la-masiva" tabindex="-1">11.1 Cuotas de ventas dentro de la masiva <a class="header-anchor" href="#_11-1-cuotas-de-ventas-dentro-de-la-masiva" aria-label="Permalink to &quot;11.1 Cuotas de ventas dentro de la masiva&quot;">​</a></h3><p>Ver secciones 2.3 y 2.5. <code>clsFacturacionCuotas</code> precarga en un solo paso cuotas, IVA e ítems de venta agrupados por cuenta, descuento y plan (<code>clsFacturacionCuotas.cs:126-172</code>). El ítem de cuota lleva el IVA y la percepción calculados por <code>clsComprobanteFactura.GetPercepcionCuota</code> (IIBB solo si la base supera el mínimo, <code>:69-94</code>). Al emitir, la cuota queda <code>ESTADO = &#39;F&#39;</code> con <code>ID_FAC</code> (<code>clsComprobanteFactura.cs:1208-1222</code>, <code>1256-1273</code>).</p><p><code>GetComprobantes_Generados</code> + <code>ImprimirComprobantes</code> (<code>clsFacturacionCuotas.cs:174-374</code>) calculan <strong>gastos de franqueo</strong>: cuentan las &quot;hojas&quot; que recibirá cada cuenta (facturas del rango, más servicios con consumos pendientes, más no medidos no facturados, considerando talones agrupados) y asignan un importe según una tabla de cantidad de hojas × zona.</p><h3 id="_11-2-importaciones-de-terceros-clsfacturacioncuotasterceros" tabindex="-1">11.2 Importaciones de terceros (<code>clsFacturacionCuotasTerceros</code>) <a class="header-anchor" href="#_11-2-importaciones-de-terceros-clsfacturacioncuotasterceros" aria-label="Permalink to &quot;11.2 Importaciones de terceros (\`clsFacturacionCuotasTerceros\`)&quot;">​</a></h3><p>Formatos según <code>ARCHIVOS.REF_ARC</code> (<code>clsFacturacionCuotasTerceros.cs:348-379</code>):</p><table tabindex="0"><thead><tr><th>Código</th><th>Fuente</th><th>Clave de cuenta</th></tr></thead><tbody><tr><td>EMA</td><td>Excel: cuenta, concepto, cantidad, precio, descripción</td><td><code>COD_SUM</code></td></tr><tr><td>SAM</td><td>EMA + archivo de ancho fijo (cuenta, titular, importe) con un concepto fijo; variante &quot;Tasa Verde&quot; con observación</td><td><code>COD_SUM</code></td></tr><tr><td>EME</td><td>DBF (emergencias médicas) → CSV; agrupa por cuenta y adherente</td><td><code>COD_SUM</code></td></tr><tr><td>CT1</td><td>Texto ancho fijo: socio, período, factura, importe; concepto de <strong>V2(2284)</strong>; error si el socio no tiene o tiene varios servicios</td><td>socio → servicio</td></tr><tr><td>FAR</td><td>Facturas de farmacia (medicamentos/perfumería)</td><td>—</td></tr><tr><td>IAL</td><td>Alumbrado público: número de suministro, importe, descripción</td><td><code>NUM_SUM</code></td></tr><tr><td>CEL</td><td>Celulares: número de línea → servicio conectado (o dado de baja)</td><td><code>NUM_MED</code></td></tr></tbody></table><p><code>Fill_Comprobantes</code> (<code>:883-939</code>) completa titular y situación de IVA, marca errores (&quot;CUENTA INEXISTENTE&quot;, &quot;CONCEPTO INEXISTENTE&quot;) y calcula el IVA por concepto y situación (<code>ALI_IVA_CF</code>). Luego se graba de dos maneras:</p><ul><li><code>Guardar_Comprobantes</code> (<code>:941-1052</code>): como <strong>comprobantes de venta con cuotas</strong> (<code>COMP_VEN</code>/<code>DEUDAVTA</code>) que la masiva facturará después; numeración propia bloqueando <code>COMP_VEN</code>.</li><li><code>Guardar_Facturas</code> (<code>:1054-1163</code>): como <strong>facturas directas</strong>, en bloques de 300 SQL, con número consecutivo.</li><li>Facturas de gas importadas (<code>ImportarFacturasGAS</code>/<code>Guardar_Facturas_GAS</code>, <code>:668-817</code>): Excel con cuenta, tipo, punto de venta, número, emisión, vencimiento, importe y usuario; rechaza números repetidos en el archivo.</li></ul><h3 id="_11-3-servicios-de-terceros-clsfacturacionserviciosterceros" tabindex="-1">11.3 Servicios de terceros (<code>clsFacturacionServiciosTerceros</code>) <a class="header-anchor" href="#_11-3-servicios-de-terceros-clsfacturacionserviciosterceros" aria-label="Permalink to &quot;11.3 Servicios de terceros (\`clsFacturacionServiciosTerceros\`)&quot;">​</a></h3><p>Formato &quot;PR1&quot; (telefonía móvil revendida, <code>clsFacturacionServiciosTerceros.cs:86-300</code>): CSV con línea, nota de venta, cliente, concepto (SERVICIO, SERVICIO_PROPORCIONAL, CARGO, ABONO, ABONO REINTEGRO, ABONO PROPORCIONAL, CONSUMO, CONSUMO_CPP), detalle e importe. Busca el servicio por número de línea; el ABONO toma el cargo fijo de la categoría; CONSUMO/CONSUMO_CPP generan <code>CONS_SER</code> con clave de llamada u operador. Reporta líneas no encontradas, duplicadas y servicios activos no importados. <code>Save</code> (<code>:333-379</code>) graba <code>PRCAGAS</code> del período y los consumos.</p><h3 id="_11-4-datos-extra-de-terceros-en-la-factura-clsfacturas-datosextras" tabindex="-1">11.4 Datos extra de terceros en la factura (<code>clsFacturas_DatosExtras</code>) <a class="header-anchor" href="#_11-4-datos-extra-de-terceros-en-la-factura-clsfacturas-datosextras" aria-label="Permalink to &quot;11.4 Datos extra de terceros en la factura (\`clsFacturas_DatosExtras\`)&quot;">​</a></h3><p>Con <strong>V2(2081)</strong> = OSSE, importa un DBF de la empresa de agua y lo asocia a las facturas por zona/sector/recorrido de lectura (<code>FAC_EXTRAS</code>), para imprimir datos de otro prestador en la misma factura (<code>clsFacturas_DatosExtras.cs:17-160</code>).</p><hr><h2 id="_12-impresion-talones-y-codigo-de-barras" tabindex="-1">12. Impresión, talones y código de barras <a class="header-anchor" href="#_12-impresion-talones-y-codigo-de-barras" aria-label="Permalink to &quot;12. Impresión, talones y código de barras&quot;">​</a></h2><h3 id="_12-1-seleccion-del-reporte" tabindex="-1">12.1 Selección del reporte <a class="header-anchor" href="#_12-1-seleccion-del-reporte" aria-label="Permalink to &quot;12.1 Selección del reporte&quot;">​</a></h3><p><code>DatosImpresion_Factura.NombreReporte</code> (<code>clsFacturasImpresion.cs:385-451</code>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base = V2(565)</span></span>
<span class="line"><span>si se forzó un reporte y existe -&gt; ese</span></span>
<span class="line"><span>si es CVLP -&gt; &quot;Facturacion_Factura_CVLP&quot;</span></span>
<span class="line"><span>si no: TIPO_FAC.REPORTE, o el REPORTE del primer servicio de la factura que lo tenga,</span></span>
<span class="line"><span>       o &quot;Facturacion_Factura&quot;; si es prepaga y existe V2(156) -&gt; ese</span></span>
<span class="line"><span>prefijos opcionales si existe el archivo: &quot;e_&quot; (modelo electrónico), &quot;2_&quot; (alternativo), &quot;t_&quot; (talón sumado)</span></span>
<span class="line"><span>sufijos opcionales si existe el archivo: &quot;_&lt;COD_COM&gt;&quot; y luego &quot;_&lt;COD_SIT con 3 dígitos&gt;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Es decir, <strong>la variación por cooperativa se resuelve con archivos de reporte con nombre convencional</strong> (DevExpress), no con código. Otros datos que expone el modelo de impresión: código LINK = cuenta con 9 dígitos (<code>:653-663</code>), domicilio histórico de la cuenta a la fecha de emisión (<code>:665-693</code>), CAE, vencimientos, código de barras AFIP (<code>:1047</code>), transacción de prepaga, constancia de percepción IIBB vigente (<code>Get_CVP</code>, <code>:2818-2834</code>). Orden de impresión: calle y número, cuenta, zona/sector/recorrido postal, comprobante, alfabético, titular, zona/sector/recorrido de lectura, código postal y cuenta (<code>:21-31</code>). Salida: todas, solo electrónicas por mail o WhatsApp, no electrónicas, todas por mail, PDF, SMS/WhatsApp (<code>:33-49</code>).</p><h3 id="_12-2-talones-agrupacion-de-facturas-para-pagar-juntas" tabindex="-1">12.2 Talones (agrupación de facturas para pagar juntas) <a class="header-anchor" href="#_12-2-talones-agrupacion-de-facturas-para-pagar-juntas" aria-label="Permalink to &quot;12.2 Talones (agrupación de facturas para pagar juntas)&quot;">​</a></h3><p><code>GenerarTalones</code> (<code>clsFacturasImpresion.cs:3477-3591</code>):</p><ul><li>Si las facturas ya tenían talón, los pasa a <code>TALONFAC_HST</code> y los borra.</li><li>Recorre las facturas ordenadas por cuenta, <code>TIPO_FAC.GRUPOTALON</code> y <code>ORDEN_TALON</code>. Todas las facturas de <strong>la misma cuenta y el mismo grupo de talón</strong> comparten un número de talón.</li><li>El talón suma los 4 importes (los créditos restan) y toma los vencimientos de la primera factura del grupo (<code>AgregarTalones</code>, <code>:3607-3631</code>).</li><li>Los números se buscan llenando <strong>huecos</strong> de la secuencia existente (<code>GetNumero</code>, <code>:3593-3605</code>); valida que el rango a usar no esté ocupado; inserción masiva (<code>BulkInsert</code>).</li></ul><p><code>GenerarCuotasDeFacturas</code> (<code>:3633-3707</code>) parte cada factura en N talones-cuota con sus propios vencimientos; la última cuota absorbe el redondeo.</p><p><code>AgregarNroPieza</code> (<code>:3709-3785</code>) numera las piezas postales por zona/sector/recorrido; <code>AsignarOrden</code> (<code>:3787-3815</code>) asigna orden y sub-orden &quot;i/n&quot; por titular y recorrido (para ensobrar varias facturas juntas).</p><h3 id="_12-3-codigo-de-barras-arquitectura" tabindex="-1">12.3 Código de barras: arquitectura <a class="header-anchor" href="#_12-3-codigo-de-barras-arquitectura" aria-label="Permalink to &quot;12.3 Código de barras: arquitectura&quot;">​</a></h3><p><code>Codigo_Base</code> (<code>ReglasNegocio.Facturacion.CodigoBarra/Codigo_Base.cs</code>) es una clase abstracta con una <strong>estrategia por formato</strong>:</p><ul><li>Cada formato implementa: generar el código para una factura, una notificación de deuda y un talón (y opcionalmente una solicitud Pagos360); <strong>leerlo</strong> (devuelve una consulta de facturas) y su ancho (<code>:240-253</code>).</li><li>El formato por defecto de la cooperativa es <strong>V2(2055)</strong> y el convenio/código de empresa <strong>V2(2255)</strong>; si falta alguno, no se imprime código (<code>:305-358</code>). Los formatos disponibles para lectura en caja son los de <code>BANCOS.ID_CODBAR</code> más el por defecto (<code>:734-746</code>).</li><li><code>Get_Instance</code> (<code>:366-477</code>) es una fábrica con unos <strong>100 formatos</strong> (enum <code>TipoCodigo</code>, <code>:15-228</code>). Varios códigos de enum apuntan a la misma clase.</li><li>La lectura rechaza caracteres no numéricos, salvo en la cooperativa &quot;EMPR&quot; (V2 2264) (<code>:279-283</code>).</li><li>Prefijos de documento usados dentro del código: <strong>40</strong> notificación, <strong>41</strong> factura (por <code>ID_FAC</code>), <strong>42</strong> talón, <strong>43</strong> solicitud Pagos360 (<code>:230-238</code>). La decodificación genérica está en <code>clsComprobanteFactura.Get_Facturas</code> (<code>clsComprobanteFactura.cs:2202-2422</code>): 41 → <code>ID_FAC</code>; 42 → número de talón; 40 → notificación (o lote + cuenta); 43 → <code>PAGOS360_ITEMS.COD_PAG</code>; 21–23 → socio/cuenta + agrupador + vencimiento; 99 → cuenta + terminaciones de número; 14 dígitos → comprobante + punto de venta + número; 16 dígitos → comprobante de 4 dígitos. Hay casos especiales por cooperativa (CL, RUF, TIO, FOT).</li></ul><p>Dígitos verificadores implementados (<code>Codigo_Base.cs:502-675</code>):</p><table tabindex="0"><thead><tr><th>Método</th><th>Algoritmo</th></tr></thead><tbody><tr><td>DV1</td><td>Ponderadores 1,3,5,7,9 (ciclando 3-5-7-9), suma/2, módulo 10 (estándar Pago Fácil/Rapipago; se aplica dos veces)</td></tr><tr><td>DV2</td><td>Ponderadores 9,7,1,3, complemento a 10 (Bancor)</td></tr><tr><td>DV3</td><td>Módulo 10 con peso 3 en posiciones pares (estilo EAN/AFIP)</td></tr><tr><td>DV4</td><td>Módulo 11 con pesos decrecientes</td></tr><tr><td>DV5</td><td>Peso 3 en impares, módulo 10 sin complemento</td></tr><tr><td>DV6</td><td>Ponderadores 1,3,5,7,9 con complemento a 10</td></tr><tr><td>DV7, DV8, DV9</td><td>Variantes propietarias (suma ponderada por posición; alfanumérico módulo 43; pesos 3..9 cíclicos)</td></tr><tr><td>CRC16-CCITT</td><td>Para QR EMVCo (<code>calculateCRC</code>, <code>:479-500</code>)</td></tr></tbody></table><p>Utilidades: importes en centavos con ceros a la izquierda (<code>Get_TextoImporte</code>, <code>:684-689</code>), fecha juliana AADDD (<code>GetJulianDate</code>, <code>:748-754</code>).</p><h3 id="_12-4-formatos-genericos-estructura" tabindex="-1">12.4 Formatos genéricos (estructura) <a class="header-anchor" href="#_12-4-formatos-genericos-estructura" aria-label="Permalink to &quot;12.4 Formatos genéricos (estructura)&quot;">​</a></h3><p>Se describen los campos, no el código.</p><ul><li><strong>Pago Fácil 42</strong> (<code>Genericos/Codigo_PagoFacil42.cs:39-57</code>): empresa (4) + importe 1º vto (8, centavos) + año de emisión (2) + día juliano del 1º vto (3) + comprobante (2) + punto de venta (4) + número (8) + &quot;0&quot; + recargo 2º vto (6) + días entre 1º y 2º vto (2) + DV1 + DV1. Para notificaciones y talones se reemplaza comprobante/número por &quot;40&quot;/&quot;42&quot; + &quot;0000&quot; + número de 8 y el recargo por ceros. Si el largo no da 42, imprime ceros. La lectura valida ambos DV y reconstruye comprobante+punto de venta+número.</li><li><strong>Banco de Córdoba 50</strong> (<code>Genericos/Codigo_BancoCordoba50.cs:34-48</code>): empresa (4) + &quot;03&quot; + identificador de 14 (comprobante 2 + pto. venta 4 + número 8; en la cooperativa &quot;AO&quot;, el <code>ID_FAC</code> con 14 dígitos) + 1º vto AAMMDD + importe 1º (9) + días al 2º (2) + recargo 2º (5) + días al 3º (2) + recargo 3º (5) + DV2.</li><li><strong>Procoop 14</strong> (<code>Clientes/PR_General_14.cs:17-30</code>): comprobante (2) + punto de venta (4) + número (8); notificación &quot;40&quot; + 12 dígitos; talón &quot;42&quot; + 12 dígitos. Sin DV.</li><li><strong>AFIP</strong> (<code>Genericos/Codigo_Varios_AFIP.cs:15-28</code>): CUIT de la empresa + comprobante (2) + punto de venta (4) + CAE + vencimiento CAE AAAAMMDD + DV3; debe dar 40 caracteres. Solo generación.</li><li><strong>Credicoop</strong> (<code>Genericos/Codigo_BancoCredicoop.cs</code>): solo lectura (47): cuenta de 6, dos terminaciones de número de 4, año de 2, días desde fin del año anterior.</li><li>Otros genéricos: Pago Fácil 46/50 (con variantes de 11 dígitos de importe), Banco de Córdoba 43/48/56, Banco Nación 38, Mutual Independiente. Su detalle está en 12.4.1.</li></ul><p><em>Segunda pasada</em>: se confirmaron contra el código las estructuras de Pago Fácil 42 y Banco de Córdoba 50 descritas arriba.</p><h4 id="_12-4-1-resto-de-los-formatos-genericos-segunda-pasada" tabindex="-1">12.4.1 Resto de los formatos genéricos (segunda pasada) <a class="header-anchor" href="#_12-4-1-resto-de-los-formatos-genericos-segunda-pasada" aria-label="Permalink to &quot;12.4.1 Resto de los formatos genéricos (segunda pasada)&quot;">​</a></h4><p>Convenciones que comparten todos los formatos:</p><ul><li>&quot;Importe N&quot; es <code>Get_TextoImporte</code>: valor absoluto en centavos con ceros a la izquierda (<code>Codigo_Base.cs:684-689</code>). <strong>Los créditos pierden el signo</strong> y un importe más ancho que el campo <strong>no se trunca</strong>, lo que alarga el código <strong>[VERIFICAR]</strong> si hay facturas grandes.</li><li>Las fechas usan <code>Get_FechaTexto</code> (<code>Codigo_Base.cs:691-723</code>), un formato propio en el que &quot;mm&quot; es el <strong>mes</strong> y &quot;MM&quot; son los minutos, al revés que en .NET.</li><li>&quot;Juliano&quot; es el día del año con 3 dígitos. &quot;Días2&quot; es la cantidad de días entre el 1º y el 2º vencimiento, con 2 dígitos.</li><li>&quot;Recargo&quot; es <code>TOTAL2 − TOTAL1</code> salvo que se diga otra cosa.</li><li>Si falta la factura, el código queda en ceros del ancho del formato (<code>Codigo_Base.cs:305-358</code>).</li></ul><table tabindex="0"><thead><tr><th>Formato (largo)</th><th>Factura: campos en orden</th><th>DV</th><th>Notificación / talón</th><th>Lectura</th></tr></thead><tbody><tr><td><strong>Pago Fácil 46</strong> (46) (<code>Genericos/Codigo_PagoFacil46.cs:47-80</code>)</td><td>convenio 3 + importe 1º vto 8 + año del VTO1 2 + juliano VTO1 3 + &quot;41&quot; + <code>ID_FAC</code> 13 + &quot;0&quot; + importe 2º vto 8 + año VTO2 2 + juliano VTO2 3</td><td>DV1 una vez</td><td>Notificación: convenio + deuda 8 + año y juliano de <code>VTO_CIR</code> (o fecha + 30) + &quot;0&quot; + &quot;40&quot; + &quot;0000&quot; + <code>CNT_NOT</code> 8 + relleno de ceros. Talón: importe en ceros + &quot;042&quot; + &quot;0000&quot; + número 8</td><td><code>:9-46</code>: salta 3, importe 8, fecha 5, identificador 15. Si empieza con &quot;4100…&quot; o &quot;4200…&quot; va al decodificador genérico. Si no, cae en el modo heredado: número = primeros 6, sucursal = caracteres 7-8, VTO1 comparado contra dos bases julianas y desempate por <code>SALDO</code>. Una notificación (&quot;0400…&quot;) <strong>cae en el modo heredado</strong> <strong>[VERIFICAR]</strong></td></tr><tr><td><strong>Pago Fácil 46_2</strong> (46) (<code>Genericos/Codigo_PagoFacil46_2.cs:36-80</code>)</td><td>convenio 4 + importe 11 + año 2 + juliano VTO1 3 + &quot;41&quot; + <code>ID_FAC</code> 12 + recargo 8 + días VTO2−VTO1 2</td><td>DV1 + DV1</td><td>Talón: &quot;42&quot; + número 12 con el mismo esquema. Notificación: <strong>no implementada</strong> (lanza excepción). Si el largo no da 46, devuelve ceros</td><td><code>:9-35</code>: valida ambos DV y pasa al decodificador genérico con la fecha</td></tr><tr><td><strong>Pago Fácil 50</strong> (50) (<code>Genericos/Codigo_PagoFacil50.cs:37-70</code>)</td><td>convenio 6 + &quot;00&quot; + &quot;41&quot; + <code>ID_FAC</code> 12 + VTO1 AAMMDD + importe 9 + 12 ceros</td><td>DV2</td><td>Notificación y talón con el mismo layout (&quot;40&quot;/&quot;42&quot;); el talón usa <code>SALDO</code> como importe</td><td><code>:9-36</code>: valida DV2, luego decodificador genérico. Modo heredado: cuenta + número 8 + vencimiento</td></tr><tr><td><strong>Pago Fácil 50_2</strong> (50) (<code>Genericos/Codigo_PagoFacil50_2.cs:39-75</code>)</td><td>convenio 4 + importe 8 + año 2 + juliano 3 + &quot;41&quot; + <code>ID_FAC</code> 12 + &quot;0&quot; + recargo 2º 6 + días2 2 + recargo 3º (<code>TOTAL3 − TOTAL1</code>) 6 + días VTO3−VTO1 2</td><td>DV1 + DV1</td><td>Talón con &quot;42&quot;. Notificación no implementada</td><td><code>:9-38</code>: valida DV y usa el decodificador genérico</td></tr><tr><td><strong>Banco de Córdoba 43</strong> (43) (<code>Genericos/Codigo_BancoCordoba43.cs:39-72</code>)</td><td>convenio 4 + <code>ID_FAC</code> 8 + &quot;41&quot; + período MM + AAAA + VTO1 AAAAMMDD + días2 2 + importe 1º 6 + importe 2º 6</td><td>DV3</td><td>Notificación: <code>CNT_NOT</code> 8 + &quot;40&quot; + mes + año + fecha + &quot;00&quot; + deuda 6 + 6 ceros. Talón: número 8 + &quot;42&quot; + <code>FEC_ALTA</code> AAAAMM + AAAAMMDD + 14 ceros (sin importe)</td><td><code>:9-38</code>: salta 4 y reordena 10 caracteres como &quot;41&quot; + id. Modo heredado: <code>RUTA_SR</code> &quot;nnnnnnn/nnn&quot;. <strong>El importe de 6 dígitos limita a $ 9.999,99</strong> <strong>[VERIFICAR]</strong></td></tr><tr><td><strong>Banco de Córdoba 48</strong> (48) (<code>Genericos/Codigo_BancoCordoba48.cs:32-52</code>)</td><td>convenio 4 + &quot;300&quot; + <code>COD_COM</code> 4 + <code>SUC_COM</code> 4 + <code>NUM_COM</code> 8 + importe 8 + VTO1 AAAAMMDD + recargo 6 + días2 2</td><td>DV1</td><td>Solo facturas</td><td><code>:9-31</code>: pasa 16 dígitos (comprobante de 4) al decodificador genérico</td></tr><tr><td><strong>Banco de Córdoba 50_2</strong> (50) (<code>Genericos/Codigo_BancoCordoba50_2.cs:33-70</code>)</td><td>convenio 4 + &quot;03&quot; + <code>COD_COM</code> 4 + <code>SUC_COM</code> 4 + <code>NUM_COM</code> 8 + VTO1 AAMMDD + importe 9 + días2 2 + recargo 2º como <strong>% de TOTAL1</strong> (4, con 2 decimales) + días VTO3−VTO2 2 + recargo 3º % 4</td><td>DV2</td><td>Talón: &quot;42&quot; + número 14. Pagos360: &quot;03&quot; + &quot;43&quot; + 000000 + <code>COD_PAG</code> 8, pero el tercer tramo <strong>repite VTO2−VTO2 = 0 y el recargo 2º</strong> (bug). Con <code>TOTAL1 = 0</code> hay <strong>división por cero</strong></td><td><code>:9-32</code>: decodificador genérico</td></tr><tr><td><strong>Banco de Córdoba 56</strong> (56) (<code>Genericos/Codigo_BancoCordoba56.cs:44-76</code>)</td><td>convenio 6 + &quot;41&quot; + <code>ID_FAC</code> 14 + VTO1 AAMMDD + importe 1º 9 + días2 2 + <code>TOTAL2</code> 7 + días3 (desde VTO1) 2 + <code>TOTAL3</code> 7</td><td>DV2</td><td>Notificación / talón: convenio 4 + &quot;00&quot; + &quot;40&quot;/&quot;42&quot; + número 14 + fecha + ceros</td><td><code>:9-43</code>: salta 4, grupo 2, tipo 2, id 14. Si el tipo no es 40/41/42, modo heredado por <code>FACTURAS.USUARIO = grupo + id</code> <strong>[VERIFICAR]</strong></td></tr><tr><td><strong>Banco Nación 38</strong> (38) (<code>Genericos/Codigo_BancoNacion_38.cs:34-49</code>)</td><td>convenio 4 + &quot;000000&quot; + &quot;41&quot; + <code>ID_FAC</code> 12 + VTO1 DDMMAA + importe 8</td><td>Sin DV</td><td>Análogos con &quot;40&quot;/&quot;42&quot;</td><td><code>:9-33</code>: decodificador genérico; modo heredado cuenta + número 8 + DDMMAA</td></tr><tr><td><strong>Mutual Independiente</strong> (50) (<code>Genericos/Codigo_Mutual_Independiente.cs:33-53</code>)</td><td>convenio 4 + &quot;00&quot; + <code>COD_COM</code> 2 + <code>SUC_COM</code> 4 + <code>NUM_COM</code> 8 + VTO1 AAMMDD + importe 9 + días2 2 + recargo 2º 5 + días VTO3−VTO2 2 + recargo <code>TOTAL3 − TOTAL2</code> 5</td><td>DV2</td><td>Solo facturas</td><td><code>:9-32</code>: decodificador genérico</td></tr><tr><td><strong>Credicoop</strong> (47) (<code>Genericos/Codigo_BancoCredicoop.cs:9-49</code>)</td><td>No genera</td><td>—</td><td>—</td><td>Salta 4, cuenta 6, terminaciones de número 4 + 4, 8 ignorados, año 2, días desde fin del año anterior 3, y luego 6 + 2 + 6 + 2. Bug del año de 2 dígitos ya listado en §16</td></tr><tr><td><strong>AFIP</strong> (40) (<code>Genericos/Codigo_Varios_AFIP.cs:15-40</code>)</td><td>CUIT + <code>COD_COM</code> 2 + <code>SUC_COM</code> 4 + CAE + vto CAE AAAAMMDD</td><td>DV3</td><td>No aplica</td><td>No lee. Si el largo no es 40 devuelve vacío; <code>Get_AnchoCodigo</code> lanza excepción</td></tr></tbody></table><p>Métodos de <code>Codigo_Base</code> revisados:</p><ul><li><code>Get_TipoCodigosTable</code> (<code>Codigo_Base.cs:254</code>): combina <code>BANCOS.ID_CODBAR</code> con V2 2055.</li><li><code>Get_Facturas</code> (<code>:279-283</code>): rechaza entradas no numéricas salvo con la sigla EMPR.</li><li>Los <code>Get_CodigoBarras</code> por defecto usan V2 2055 y V2 2255.</li></ul><p>Métodos sin regla de negocio: <code>Get_AnchoCodigo</code> (en todas las clases genéricas; solo devuelve el largo).</p><h3 id="_12-5-como-varia-por-cooperativa" tabindex="-1">12.5 Cómo varía por cooperativa <a class="header-anchor" href="#_12-5-como-varia-por-cooperativa" aria-label="Permalink to &quot;12.5 Cómo varía por cooperativa&quot;">​</a></h3><p>La carpeta <code>CodigoBarra.Clientes</code> tiene ~90 clases con prefijo de la sigla de la cooperativa (ARR, ALM, BAT, CAU, MONT, TREL, etc.) o del recaudador (PR_ = Procoop genérico). Patrones:</p><ul><li>Mismo layout bancario con otro identificador (ID_FAC en vez de comprobante; cuenta en vez de número).</li><li>Distinta cantidad de vencimientos codificados y distinto cálculo de &quot;días al 2º/3º vto&quot;. Ejemplo <strong>Arroyito 54</strong> (<code>Clientes/ARR_General_54.cs:19-28</code>): &quot;1&quot; si el tipo de factura es &quot;EN&quot; (energía) o &quot;2&quot; en otro caso + &quot;0&quot; + &quot;41&quot; + <code>ID_FAC</code> (14) + 1º vto AAAAMMDD + 3 pares (días, importe); para tipos &quot;FN&quot;/&quot;SG&quot; y talones con cuota, los días se calculan hasta el último día hábil del mes.</li><li>QR de billeteras (EMVCo): Pagos360, SIRO, NaranjaX, Pronto Pago, ProvinciaNet, Helipagos.</li><li>Recaudadores: Rapipago, Pago Fácil, Cobro Express, Bapro, Banco Roela/SIRO, Bersa, Santa Fe, Provincia Net, Pampa Pagos.</li></ul><p><em>Patrón común (segunda pasada)</em>: cada clase de <code>Clientes</code> hereda de <code>Codigo_Base</code> y reutiliza los mismos bloques que los genéricos:</p><ul><li>convenio (V2 2255);</li><li>prefijo 40/41/42/43 más el identificador (<code>ID_FAC</code>, talón o <code>CNT_NOT</code>);</li><li>uno a cuatro pares (vencimiento, importe o recargo) en fecha juliana, AAMMDD o AAAAMMDD;</li><li>uno de los DV de 12.3.</li></ul><p>La lectura casi siempre delega en el decodificador genérico de <code>clsComprobanteFactura.Get_Facturas</code> y agrega un modo heredado propio (número + sucursal, cuenta o <code>RUTA_SR</code>). Lo que cambia entre cooperativas es el orden, el ancho y el criterio de días entre vencimientos, no la semántica. El caso de Laguna Larga se documenta en el doc 11.</p><h3 id="_12-6-pagos360" tabindex="-1">12.6 Pagos360 <a class="header-anchor" href="#_12-6-pagos360" aria-label="Permalink to &quot;12.6 Pagos360&quot;">​</a></h3><ul><li>Una solicitud de cobro (<code>PAGOS360</code>, con ítems <code>PAGOS360_ITEMS</code> por factura o talón) guarda hasta tres códigos de barra (<code>CODIGO_BARRA</code>, <code>CODIGO_BARRA2</code>, <code>CODIGO_BARRA3</code> &quot;1M&quot;) y un <code>QR_ID</code>. La impresión toma la primera solicitud no en estado 4 (<code>clsFacturasImpresion.cs:2730-2793</code>).</li><li>QR Pagos360 (<code>Clientes/PR_Pagos360_QR.cs:15-51</code>): solo si la solicitud tiene <code>QR_ID</code>, no es débito automático (<code>DEBITO_ID</code> nulo) y el 2º vencimiento no pasó. Arma un string EMVCo: formato &quot;01&quot;, QR dinámico &quot;12&quot;, identificador <code>com.pagos360</code>, CUIT de la empresa (<strong>V2 519</strong>), MCC (<strong>V2 2773</strong>), moneda 032, país AR, nombre (<strong>V2 2759</strong>, ≤ 25), ciudad (<strong>V2 2761</strong>, ≤ 15), código postal (<strong>V2 2760</strong>), dato adicional con el <code>QR_ID</code>, y CRC16 final.</li><li>El prefijo 43 en un código leído en caja identifica la solicitud (<code>clsComprobanteFactura.cs:2320-2327</code>).</li><li>La anulación consulta el estado de la solicitud (estados 0, 1 y 4 = no cobrada) antes de permitir eliminar (sección 7.1). La creación de solicitudes y su conciliación están en el doc 05.</li><li>SIRO QR (<code>Clientes/PR_SIRO_QR.cs</code>) usa el CUIT de <strong>V2 2798</strong>, genera UUID deterministas y puede crear la solicitud al imprimir; el 3º vencimiento del QR puede forzarse con <strong>V2 3144</strong>.</li></ul><hr><h2 id="_13-interfaces-con-entes-reguladores" tabindex="-1">13. Interfaces con entes reguladores <a class="header-anchor" href="#_13-interfaces-con-entes-reguladores" aria-label="Permalink to &quot;13. Interfaces con entes reguladores&quot;">​</a></h2><h3 id="_13-1-enargas-gas" tabindex="-1">13.1 ENARGAS (gas) <a class="header-anchor" href="#_13-1-enargas-gas" aria-label="Permalink to &quot;13.1 ENARGAS (gas)&quot;">​</a></h3><ul><li><code>clsEnargas</code> (<code>clsEnargas.cs</code>): genera los archivos del protocolo SARI. Archivos FDU, DET, CMD, USR, RAU, FDC, FDD, RZF-DS y, solo para la cooperativa &quot;BOL&quot;, SUP (<code>:111-123</code>, <code>:442-467</code>). Nombre: <code>&amp;lt;distribuidor 5 dígitos&gt;_&amp;lt;número&gt;_&amp;lt;archivo&gt;_&amp;lt;AAAA-MM&gt;_&amp;lt;fecha&gt;.TXT</code>, tabulado (SUP con coma), en <code>ENARGAS\\</code> junto al ejecutable (<code>:779-849</code>). También exporta Excel de morosidad y de facturas (<code>:469-777</code>). Las tablas maestras (categorías, documentos, subzonas, localidades) vienen de <code>SARI_Protocolo_Tablas(2).xlsx</code>, según <strong>V2 2603</strong> (<code>:136-143</code>). <em>Corrección (segunda pasada)</em>: el archivo se llama <code>SARI_Protocolo_Tablas2.xlsx</code> si V2 2603 ≠ 0 y <code>SARI_Protocolo_Tablas.xlsx</code> si no. Se busca en la carpeta <code>Recursos</code> del directorio del ejecutable (<code>AppDomain BaseDirectory</code>), no del servidor (<code>clsEnargas.cs:136-147</code>). Mapea categorías por <code>CATE_SER.COD_ENGAS</code>, grupo, cuadro (P/S/H/Z/T se informan como &quot;a&quot;) y segmentación de subsidio (<code>CATE_SER_EXTRAS.GRUPO_SUBSIDIO</code>) (<code>:851-866</code>).</li><li><code>clsEnargas2</code> (<code>clsEnargas2.cs</code>): protocolo nuevo &quot;FCU-DS&quot; con archivos FaC, Sub, FaD, CoC, Usr, FaV y SICC (<code>:19-29</code>, <code>:178-224</code>); con <strong>V2 3174</strong> usa la matrícula como identificador.</li><li><strong>Bloques de consumo subsidiado</strong> (segmentación N2/N3/CS): <code>GetTempModifBonif</code> calcula para cada servicio con consumos pendientes el nuevo bloque bonificado (<code>SERSOC.CANTIDAD</code>) como suma, por cada mes cubierto por la lectura, de <code>días del mes leídos × cantidad mensual de ENGAS_CANTMESES / días del mes</code>, dividido 2 (<code>:2837-3014</code>). <code>RegistrarModifSegmentacion</code> lo graba (con tabla temporal <code>TEMPMODIFBONIF</code>) y <code>LimpiarBloquesServicios</code> lo pone en 0.</li></ul><h3 id="_13-2-enacom-telecomunicaciones" tabindex="-1">13.2 ENACOM (telecomunicaciones) <a class="header-anchor" href="#_13-2-enacom-telecomunicaciones" aria-label="Permalink to &quot;13.2 ENACOM (telecomunicaciones)&quot;">​</a></h3><ul><li><code>clsEnacom</code> (<code>clsEnacom.cs</code>) es solo la configuración: para telefonía fija, móvil, internet y TV, qué servicios principales, servicios, productos e impuestos componen cada uno. Se guarda serializada en <code>Recursos\\ENACOM_Config.txt</code> del servidor (<code>ConfiguracionEnacom.cs:23-58</code>).</li><li><code>Exportar_Excel_ENACOM_DNU_RES_367_2020</code> (<code>ConfiguracionEnacom.cs:61-189</code>): CSV puntual del DNU 311/2020 (Res. 367/2020): por cuenta con el servicio conectado (altas hasta el 25/03/2020 si se indica fecha de deuda), documento, domicilio, prestador (CUIT), tipo de servicio, plan (categoría), montos facturados de enero a abril 2020 y deuda acumulada (ítems de los servicios/productos/impuestos configurados, créditos restan). Es un informe histórico.</li></ul><h3 id="_13-3-otros-archivos-reglasnegocio-facturacion-archivos" tabindex="-1">13.3 Otros archivos (<code>ReglasNegocio.Facturacion.Archivos</code>) <a class="header-anchor" href="#_13-3-otros-archivos-reglasnegocio-facturacion-archivos" aria-label="Permalink to &quot;13.3 Otros archivos (\`ReglasNegocio.Facturacion.Archivos\`)&quot;">​</a></h3><p>Exportadores de texto con <code>ExportBase</code> (codificación Windows-1252, campos de ancho fijo) (<code>ExportBase.cs</code>). Se listan para ubicar su lugar; el contenido fiscal es del doc 03:</p><ul><li>RG 1361 duplicados electrónicos, RG 3685 / RG 3685_ITEMS (Régimen de Información de Compras y Ventas; con <strong>V2 2692</strong> usa vencimiento en vez de emisión), RG 3349 consumos relevantes, RG 3571 Rendición de Comprobantes de Servicios Públicos (y RG 46/2019 con generadores), SICORE, SIRCAR, retenciones municipales e Ingresos Brutos de varias provincias, FEDECOBA y la Circular 70/2021 del ERSeP (<code>TipoArchivos.cs</code>).</li><li><code>clsMovimientoConceptos</code> (<code>clsMovimientoConceptos.cs:17-49</code>) es el informe de &quot;movimiento de conceptos&quot; (facturado/cobrado por concepto, categoría, rubro, rendición, IIBB, intereses, impuestos, ranking), con exportadores por cooperativa (<code>clsMovimientoConceptos_Exportacion</code>: CAU_IIBB, ARR_AMA, TORN_ALP).</li></ul><h4 id="_13-3-1-detalle-de-archivos-segunda-pasada" tabindex="-1">13.3.1 Detalle de <code>Archivos</code> (segunda pasada) <a class="header-anchor" href="#_13-3-1-detalle-de-archivos-segunda-pasada" aria-label="Permalink to &quot;13.3.1 Detalle de \`Archivos\` (segunda pasada)&quot;">​</a></h4><p><strong><code>ExportBase</code></strong> (<code>Archivos/ExportBase.cs</code>):</p><ul><li><code>Exportar</code> escribe en Windows-1252.</li><li><code>ExportarCSV</code> (<code>:49</code>) separa con &quot;;&quot;. Cada fila termina en &quot;;&quot;, pero la cabecera no, y usa la codificación por defecto (no 1252).</li><li><code>Get_TextoNumero</code> rellena con ceros; si el valor es negativo, reserva un lugar para el signo (ancho − 1).</li><li><code>Get_Texto</code> rellena o trunca al ancho.</li><li><code>Get_ComboInfoArchivo</code> (<code>:163</code>) ofrece RG 3571 (código 8) y RG 3685 (código 16).</li><li><code>Get_TipoAnalisisArchivo</code> (<code>:173</code>): RG 3571 admite análisis por número de línea y por correlatividad; RG 3685 solo por línea.</li><li><code>Get_InfoLinea</code> y <code>Get_InfoCorrelatividad</code> (<code>:190</code>, <code>:195</code>) son virtuales y lanzan excepción si la subclase no los implementa.</li></ul><p><strong>RG 3571</strong> (<code>Archivos/RG3571.cs</code>):</p><ul><li><code>Get_InfoLinea</code> (<code>:1343</code>) decodifica una línea del archivo ya generado por posiciones fijas. En los importes, el signo &quot;0&quot; significa positivo.</li><li><code>Get_InfoCorrelatividad</code> (<code>:1381</code>) ordena por código AFIP, punto de venta y número. Ante un salto informa solo <code>número − 1</code>, no el rango faltante completo.</li><li>El punto de venta se lee como <code>substring(2,5)</code> en la correlatividad y como <code>substring(3,4)</code> en <code>Get_InfoLinea</code> <strong>[VERIFICAR]</strong>.</li></ul><p><strong>RG 3685</strong> y <strong>RG 3685_ITEMS</strong>:</p><ul><li><code>Get_ComprobatesBC</code> (<code>RG3685.cs:899</code>) lista los códigos AFIP de comprobantes B y C; la lista de <code>RG3685_ITEMS</code> no incluye el &quot;109&quot;.</li><li><code>Get_InfoLinea</code> (<code>RG3685.cs:910</code>, <code>RG3685_ITEMS.cs:740</code>) solo acepta líneas de 266 caracteres.</li></ul><p><strong>FEDECOBA</strong> (<code>Archivos/FEDECOBA.cs:15</code>):</p><ul><li>Exporta los saldos contables de <code>CTITASIE</code> agrupados por la cuenta FEDECOBA del plan (<code>CTPLAN.FEDECOBA</code>), partidos en N archivos.</li><li>Tiene un CUIT fijo en el código; no se transcribe.</li><li>El contador de registros no se reinicia entre archivos (bug).</li></ul><p><strong>Archivos fiscales de compras y retenciones</strong>: pertenecen al doc 03 y aquí solo se ubican.</p><ul><li><code>PercepcionSICORE</code>: <ul><li>Métodos <code>Exportar_Sueldos</code> (<code>:79</code>), <code>Venta</code> y <code>Proveedores</code> (<code>:133</code>).</li><li>V2 2991 hace que Venta use coma decimal; V2 2539 aplica el formato internacional en Proveedores.</li><li>Sin CUIT se usa 23333333333.</li><li>Proveedores usa impuesto 0217 con régimen 078, o 0767 con 214 para Buenos Aires.</li><li>Sueldos toma <code>TIP_CON</code> 40 (Ganancias).</li></ul></li><li><code>RetencionesMunicipales</code>: <ul><li>Registros C/D/P separados por &quot;;&quot;, con el CUIT de V2 519 y la razón social de V2 518.</li><li>IIBB usa el artículo 020 para RUF y 001 para el resto. Santa Fe tiene el mismo layout con campos más anchos.</li><li>La Pampa exige que todo sea del mismo mes y tiene un CUIT fijo en la cabecera.</li><li>Nombres de archivo: ARBA <code>AR-&amp;lt;cuit&gt;-AAAAMM&amp;lt;quincena&gt;-6-LOTE1</code>; A122R <code>ER-…-LOTE00001</code>.</li><li>SeguridadSocial usa códigos fijos y arma una consulta de <code>TALONFAC</code> que nunca se utiliza.</li></ul></li><li><code>SIRCAR</code> (<code>:135</code>, <code>:167</code>, <code>:200</code>): <ul><li>Retenciones de Córdoba y Río Negro, y percepciones; la jurisdicción 904 agrega el campo de constancia.</li><li>Buenos Aires valida los CUIT y aborta con la lista de los erróneos.</li><li>El nombre del archivo depende de la versión (v12 o anterior).</li></ul></li></ul><hr><h2 id="_14-parametros-busca-v2-que-condicionan-el-proceso" tabindex="-1">14. Parámetros <code>Busca_V2_*</code> que condicionan el proceso <a class="header-anchor" href="#_14-parametros-busca-v2-que-condicionan-el-proceso" aria-label="Permalink to &quot;14. Parámetros \`Busca_V2_*\` que condicionan el proceso&quot;">​</a></h2><p>Solo los vistos en estas clases. &quot;L&quot; = lógico, &quot;N&quot; = número, &quot;C&quot; = texto.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Tipo</th><th>Efecto</th><th>Cita</th></tr></thead><tbody><tr><td>21</td><td>L</td><td>Si está activa, <strong>no</strong> redondea totales a 2 decimales</td><td><code>clsComprobanteFactura.cs:612</code></td></tr><tr><td>67</td><td>C</td><td>Fecha de cierre de ventas: tope para modificar emisión</td><td><code>clsModificacionFacturas.cs:102</code>, <code>:392</code></td></tr><tr><td>74</td><td>N</td><td>Tipo de cálculo de importes 2º–4º vencimiento</td><td><code>clsComprobanteFactura.cs:1774</code></td></tr><tr><td>119</td><td>N</td><td>Redondeo de consumo de gas corregido (2 truncar, 3 redondear)</td><td><code>clsRecategorizacion.cs:323</code></td></tr><tr><td>156</td><td>C</td><td>Reporte especial para facturas de prepaga</td><td><code>clsFacturasImpresion.cs:424</code></td></tr><tr><td>242</td><td>N</td><td>Si el código de barras 22 identifica socio (1,2) o cuenta (3,4)</td><td><code>clsComprobanteFactura.cs:2273</code></td></tr><tr><td>307, 311, 543, 607, 2089, 2247</td><td>—</td><td>Deben estar configuradas para facturar</td><td><code>clsFacturacionMasiva.cs:505</code></td></tr><tr><td>519</td><td>C</td><td>CUIT de la empresa (QR)</td><td><code>PR_Pagos360_QR.cs:23</code></td></tr><tr><td>565</td><td>C</td><td>Reporte de factura por defecto</td><td><code>clsFacturasImpresion.cs:389</code></td></tr><tr><td>578</td><td>N</td><td>Tasa/monto de recargo por vencimiento</td><td><code>clsComprobanteFactura.cs:1797</code></td></tr><tr><td>606</td><td>N</td><td>Concepto de interés (para IVA del recargo)</td><td><code>clsComprobanteFactura.cs:1920</code></td></tr><tr><td>639</td><td>N</td><td>Tipo de factura de viviendas</td><td><code>clsComprobanteFactura.cs:629</code></td></tr><tr><td>739</td><td>L</td><td>Prohíbe conceptos gravados en comprobantes internos</td><td><code>clsComprobanteFactura.cs:697</code></td></tr><tr><td>1008</td><td>N</td><td>Vendedor por defecto</td><td><code>clsComprobanteFactura.cs:611</code></td></tr><tr><td>2055</td><td>N</td><td>Formato de código de barras por defecto</td><td><code>Codigo_Base.cs:309</code></td></tr><tr><td>2081</td><td>N</td><td>Tipo de impresión con datos de terceros (OSSE)</td><td><code>clsFacturas_DatosExtras.cs:22</code></td></tr><tr><td>2242</td><td>C</td><td>&quot;TEMP&quot;: recategorización de gas sin fallback al año anterior</td><td><code>clsRecategorizacion.cs:489</code></td></tr><tr><td>2255</td><td>C</td><td>Convenio / código de empresa para códigos de barra</td><td><code>Codigo_Base.cs:313</code></td></tr><tr><td>2264</td><td>C</td><td><strong>Sigla de la cooperativa</strong>: activa variantes (ARR, AO, CL, RUF, TIO, FOT, EMPR, BOL, FLOR, AZUL, FEL…)</td><td>varias</td></tr><tr><td>2271</td><td>N</td><td>Máximo de días entre hoy y el 1º vencimiento en facturas manuales</td><td><code>clsComprobanteFactura.cs:696</code></td></tr><tr><td>2284</td><td>N</td><td>Concepto para la importación CT1</td><td><code>clsFacturacionCuotasTerceros.cs:823</code></td></tr><tr><td>2315</td><td>N</td><td>Tamaño de lote de cuentas (por defecto 100)</td><td><code>clsFacturacionMasiva.cs:205</code></td></tr><tr><td>2342</td><td>N</td><td>Redondeo de prepaga</td><td><code>clsFacturacionMasiva.cs:1348</code></td></tr><tr><td>2413</td><td>L</td><td>Recargo de prepaga en ND separada</td><td><code>clsFacturacionMasiva.cs:1355</code></td></tr><tr><td>2443</td><td>L</td><td>No facturar cuotas si la cuenta no tiene ítems de servicio</td><td><code>clsFacturacionMasiva.cs:984</code></td></tr><tr><td>2498</td><td>L</td><td>Recategorización de gas por bimestres</td><td><code>clsRecategorizacion.cs:324</code></td></tr><tr><td>2515</td><td>N</td><td>Umbral de importe para comprobantes MiPyME (FCE)</td><td><code>clsComprobante.cs:218</code></td></tr><tr><td>2526</td><td>L</td><td>Emitir factura aunque dé 0 si tiene consumos</td><td><code>clsFacturacionMasiva.cs:1154</code></td></tr><tr><td>2528</td><td>C</td><td>Otra fecha de cierre para modificación masiva</td><td><code>clsModificacionFacturas.cs:396</code></td></tr><tr><td>2530</td><td>L</td><td>Recategorización de gas por fecha de lectura en vez de período</td><td><code>clsRecategorizacion.cs:325</code></td></tr><tr><td>2549</td><td>L</td><td>Permite punto de venta 0 (comprobantes con <code>PTOVTA0</code>)</td><td><code>clsComprobante.cs:445</code>, <code>clsComprobanteBase.cs:224</code></td></tr><tr><td>2564</td><td>N</td><td>Concepto para ítem de descuento</td><td><code>clsComprobanteFactura.cs:721</code>, <code>:1379</code></td></tr><tr><td>2603</td><td>N</td><td>Versión del protocolo ENARGAS</td><td><code>clsEnargas.cs:138</code></td></tr><tr><td>2692</td><td>L</td><td>RG 3685 por vencimiento</td><td><code>RG3685.cs:273</code></td></tr><tr><td>2703</td><td>N/C</td><td>Cuadro tarifario forzado y fecha de vigencia (prepaga)</td><td><code>clsDatosFacturacion.cs:515</code></td></tr><tr><td>2736</td><td>L</td><td>Desactiva capitalización automática</td><td><code>clsFacturacionMasiva.cs:552</code></td></tr><tr><td>2759, 2760, 2761, 2773</td><td>C</td><td>Nombre, CP, ciudad y MCC del comercio para QR</td><td><code>PR_Pagos360_QR.cs:25-34</code></td></tr><tr><td>2769</td><td>L</td><td>Propagar bloqueos de cobro a las facturas nuevas</td><td><code>clsFacturacionMasiva.cs:675</code></td></tr><tr><td>2798</td><td>C</td><td>CUIT para SIRO QR</td><td><code>PR_SIRO_QR.cs:52</code></td></tr><tr><td>2815</td><td>L</td><td>Excluir bajas en impresión</td><td><code>clsFacturasImpresion.cs:2907</code></td></tr><tr><td>2855</td><td>L</td><td>No registrar capital al cerrar la masiva</td><td><code>clsFacturacionMasiva.cs:705</code></td></tr><tr><td>3080</td><td>N</td><td>Importe máximo sugerido de una factura (pregunta)</td><td><code>clsComprobanteFactura.cs:701</code></td></tr><tr><td>3094</td><td>N</td><td>Concepto &quot;crédito por energía inyectada&quot;</td><td><code>clsFacturacionMasiva.cs:203</code></td></tr><tr><td>3109</td><td>L</td><td>Criterio de emisión adicional en simulación</td><td><code>clsFacturacionMasiva.cs:1230</code></td></tr><tr><td>3144</td><td>N</td><td>Días del 3º vencimiento en SIRO QR</td><td><code>PR_SIRO_QR.cs:109</code></td></tr><tr><td>3174</td><td>L</td><td>ENARGAS usa matrícula</td><td><code>clsEnargas2.cs:155</code></td></tr><tr><td>3184</td><td>L</td><td>Recategorización ignora categorías inactivas y usa orden</td><td><code>clsRecategorizacion.cs:424</code></td></tr></tbody></table><p>Variables adicionales encontradas en la segunda pasada (los valores dependen de cada base, <strong>[VERIFICAR]</strong>):</p><table tabindex="0"><thead><tr><th>Variable</th><th>Tipo</th><th>Efecto</th><th>Cita</th></tr></thead><tbody><tr><td>29</td><td>N</td><td>Concepto para anticipo; se usa como respaldo de la 403</td><td><code>clsComprobanteVenta.cs:771-810</code></td></tr><tr><td>307 / 311 / 607</td><td>N</td><td>Conceptos de interés por mora, interés anterior e interés por financiación (obligatorios)</td><td><code>clsFacturacionMasiva.cs:505</code></td></tr><tr><td>308</td><td>N</td><td>Concepto &quot;cuota en factura mensual&quot; (capital); sus ítems no se abren por producto en Movimiento de conceptos</td><td><code>clsMovimientoConceptos.cs:617</code></td></tr><tr><td>310</td><td>N</td><td>Concepto &quot;deuda de financiación&quot;</td><td><code>clsMovimientoConceptos.cs:1094</code></td></tr><tr><td>403</td><td>N</td><td>Concepto de factura en cuotas: crédito automático en ventas en cuotas; las ventas con ese concepto se marcan &quot;Exento&quot; o se excluyen del detalle de ventas</td><td><code>clsComprobanteVenta.cs:771-810</code>, <code>clsInformes_Facturacion.cs:3034</code>, <code>:3060</code></td></tr><tr><td>518–522</td><td>C</td><td>Razón social, CUIT, calle, número y barrio de la empresa (datos de transporte propio, retenciones)</td><td><code>clsComprobanteVenta.cs:1383-1493</code>, <code>clsComprobanteRendicion.cs:57-106</code></td></tr><tr><td>543</td><td>N</td><td>Código de <code>IMPUESTO</code> para IVA (ítem &quot;Alícuota X%&quot;)</td><td><code>clsComprobanteFactura.cs:1696-1718</code></td></tr><tr><td>2089 / 2247</td><td>N</td><td>Concepto de interés y concepto de descuento del comprobante de venta (contado o 1 cuota)</td><td><code>clsFacturacionMasiva.cs:505</code></td></tr><tr><td>2246</td><td>L</td><td>Mostrar importes en el comprobante de venta</td><td><code>clsComprobanteVenta.cs:1383</code></td></tr><tr><td>2257–2260</td><td>C/N</td><td>ENARGAS: código de entidad, contrato, modalidad y porcentaje o importe de comisión</td><td><code>clsEnargas.cs</code></td></tr><tr><td>2318</td><td>C</td><td>Texto de los conceptos desconocidos (por defecto &quot;CONCEPTO DESCONOCIDO&quot;)</td><td><code>clsMovimientoConceptos.cs:414</code></td></tr><tr><td>2539</td><td>L</td><td>SICORE de proveedores con formato internacional</td><td><code>Archivos/PercepcionSICORE.cs:133</code></td></tr><tr><td>2721</td><td>N</td><td>Titular para consumidor final en facturas de farmacia</td><td><code>clsFacturacionCuotasTerceros.cs:1321</code></td></tr><tr><td>2930</td><td>L</td><td>Crédito fiscal en la factura en cuotas</td><td><code>clsComprobanteVenta.cs:771-810</code></td></tr><tr><td>2953</td><td>N</td><td>Producto &quot;flete&quot; de los presupuestos</td><td><code>clsComprobanteRendicion.cs:57-106</code></td></tr><tr><td>2972</td><td>L</td><td>Separar los ítems financiados en el libro IVA ventas</td><td><code>clsMovimientoConceptos.cs:688</code>, <code>:760</code></td></tr><tr><td>2991</td><td>L</td><td>SICORE de ventas con coma decimal</td><td><code>Archivos/PercepcionSICORE.cs</code></td></tr><tr><td>3007</td><td>C</td><td>Formato de fecha del exportador TORN (por defecto ddMMyy)</td><td><code>clsMovimientoConceptos_Exportacion.cs</code></td></tr><tr><td>3039</td><td>N</td><td>Número de lote FECESCOR; se incrementa con <code>Actu_V2</code></td><td><code>clsInformes_Facturacion.cs:1266</code></td></tr></tbody></table><hr><h2 id="_15-implicancias-para-goodapps" tabindex="-1">15. Implicancias para GoodApps <a class="header-anchor" href="#_15-implicancias-para-goodapps" aria-label="Permalink to &quot;15. Implicancias para GoodApps&quot;">​</a></h2><ol><li><strong>Separar &quot;plantilla de corrida&quot; de &quot;tipo de factura&quot;.</strong> Procoop mezcla en <code>TIPO_FAC</code> la clasificación comercial y la configuración del proceso, con fechas como expresiones de texto. En GoodApps conviene una entidad <code>PlantillaFacturacion</code> versionada (servicios, filtros, reglas de vencimiento expresadas como &quot;día hábil N del mes&quot; o &quot;+N días&quot;), y una <code>CorridaFacturacion</code> inmutable con los valores ya resueltos.</li><li><strong>Corrida como máquina de estados</strong>: borrador → simulada → aprobada → emitiendo → emitida / emitida parcial / fallida → (autorizando CAE) → cerrada. Procoop no tiene &quot;aprobada&quot; ni &quot;parcial&quot;; el lote que falla deja la corrida a medias sin estado explícito. Persistir el avance por lote y permitir <strong>reanudar</strong> desde el último lote confirmado.</li><li><strong>Idempotencia</strong>: la marca <code>ULT_FAC + SEC_PER</code> por servicio es frágil (se &quot;deshace&quot; restando períodos al anular). Mejor una tabla de &quot;período facturado por servicio&quot; con referencia al comprobante, o una restricción única (servicio, período, secuencia) sobre comprobantes vigentes.</li><li><strong>Concurrencia</strong>: reemplazar el bloqueo de tabla <code>FACTMES</code> por un lock por (cooperativa/tenant, tipo de factura, período), y la numeración por <strong>secuencias por (comprobante, punto de venta)</strong> asignadas recién al confirmar el lote, con transacción única facturas + numerador (Procoop hace dos commits).</li><li><strong>Ejecución</strong>: trabajo en cola (worker) con lotes de tamaño configurable, paralelizable por lote en el <em>cálculo</em> pero con numeración secuencial al persistir para respetar el orden de reparto (zona/sector/recorrido). Exponer progreso y una tabla de errores por servicio, como hoy.</li><li><strong>Simulación de primera clase</strong>: mismo motor, sin efectos, con muestras automáticas (una cuenta por categoría, por condición fiscal, grandes/chicos) y comparación de totales contra el período anterior antes de aprobar.</li><li><strong>Resolución de comprobante y punto de venta</strong> como servicio puro y testeable: (situación IVA, servicios, signo del total, MiPyME, grupo con forzar ND) → comprobante; (servicios, usuario, equipo, empresa) → punto de venta. Validar la matriz completa antes de correr, como hace <code>ValidarDatos</code>.</li><li><strong>Totales negativos</strong>: modelar explícitamente &quot;si el neto del período da negativo, emitir NC&quot; vs. &quot;acumular como saldo a favor&quot; (caso generación distribuida). Hacerlo configurable por servicio.</li><li><strong>Electrónica</strong>: nunca persistir facturas &quot;bloqueadas −1&quot; mezcladas con bloqueos de cobro. Separar <code>estado_autorizacion</code> (pendiente/autorizada/rechazada) de <code>bloqueo_cobro</code> (causa, historial). Bloquear el arranque de una nueva corrida si hay comprobantes pendientes de CAE de más de N días.</li><li><strong>Anulación</strong>: con ARCA, la anulación de una autorizada es siempre una NC asociada (<code>RELACION_COMP</code> con &quot;informar CUIT&quot;). La eliminación física solo para no autorizadas y sin pagos; conservar copia de auditoría (equivalente a <code>ANUFAC</code>). Reproducir las opciones de reversión: revertir consumo, dejarlo pendiente para refacturar, liberar cuotas/cargos, revertir stock.</li><li><strong>Vencimientos</strong>: soportar 1 a 4 vencimientos con estrategias de recargo enchufables (fijo $, fijo % compuesto, % diario, tramas por importe, trama por vencimiento) e IVA sobre el recargo según el concepto de interés. Validar días hábiles con calendario de feriados por provincia.</li><li><strong>Código de barras</strong>: estrategia por formato (como Procoop), pero definida <strong>declarativamente</strong> (campos, longitudes, padding, DV) para no programar una clase por cooperativa. Incluir la biblioteca de DV (módulo 10 ponderado 1-3-5-7-9, 9-7-1-3, EAN, módulo 11) y QR EMVCo con CRC16. Mantener los prefijos 40/41/42/43 para compatibilidad con lo que ya tienen impreso los socios en la migración.</li><li><strong>Plantillas de impresión</strong>: la convención de nombres de reporte (<code>e_</code>, <code>2_</code>, <code>t_</code>, <code>_&amp;lt;comprobante&gt;</code>, <code>_&amp;lt;situación IVA&gt;</code>) indica cuántas variantes existen; en GoodApps resolverlo con plantillas por tenant y reglas de selección explícitas.</li><li><strong>Talones</strong>: agrupar facturas de una cuenta por &quot;grupo de talón&quot; para un único código de pago es una funcionalidad que las cooperativas usan (energía + agua + sepelio en un solo pago); modelarla como &quot;documento de pago&quot; independiente de los comprobantes fiscales.</li><li><strong>Recategorización y retroactivos</strong>: son procesos batch con vista previa, confirmación y nota de auditoría en la cuenta. Los retroactivos no generan comprobantes: generan cargos pendientes para la próxima corrida; mantener esa separación y la protección contra duplicados.</li><li><strong>Modificación masiva</strong>: limitarla a comprobantes no autorizados electrónicamente o, si lo están, solo a datos no fiscales (vencimientos 2–4 e importes con recargo). Auditar siempre.</li><li><strong>Importaciones de terceros</strong>: definir un formato canónico (cuenta/identificador, concepto, cantidad, precio, descripción) con <em>mappers</em> por origen (Excel, DBF, ancho fijo, CSV), validación previa con reporte de errores y destino elegible (cargo pendiente, cuota, factura directa).</li><li><strong>Reguladores</strong>: ENARGAS (SARI y FCU-DS, bloques subsidiados N2/N3) es imprescindible para las cooperativas de gas; ENACOM en Procoop es solo un informe puntual de 2020 y puede quedar fuera del MVP.</li><li><strong>Parámetros</strong>: los ~50 <code>Busca_V2_*</code> de este dominio deben convertirse en configuración tipada por tenant, con valores por defecto documentados; la variable 2264 (sigla) dispara comportamientos por cooperativa que deben volverse opciones explícitas.</li></ol><hr><h2 id="_16-dudas-abiertas" tabindex="-1">16. Dudas abiertas <a class="header-anchor" href="#_16-dudas-abiertas" aria-label="Permalink to &quot;16. Dudas abiertas&quot;">​</a></h2><ol><li><strong>Comportamientos posiblemente erróneos en Procoop</strong> (confirmar con usuarios antes de replicarlos o &quot;corregirlos&quot;): <ul><li>Recategorización de gas: el filtro &quot;nunca recategorizados&quot; no se aplica (el resultado del filtro se descarta) (<code>clsRecategorizacion.cs:315</code>).</li><li>En la masiva, las relaciones de comprobantes (<code>RELACION_COMP</code>) se generan con la plantilla de inserción de <code>ANTIFACTU</code> (<code>clsComprobanteFactura.cs:1501</code>). ¿Se usa en la práctica?</li><li>Importaciones de terceros a facturas o ventas: se pide un número nuevo y se usa el siguiente, lo que <strong>deja un número sin usar</strong> por cada importación (<code>clsFacturacionCuotasTerceros.cs:957/997</code>, <code>1065/1079</code>).</li><li>Lectura de Credicoop: compara el año del vencimiento con un año de 2 dígitos (<code>Codigo_BancoCredicoop.cs:28</code>).</li><li>Modificación de IVA de cuotas: para la sobretasa usa la tasa general nueva (<code>clsModificacionCuotas.cs:744</code>).</li><li>Retroactivos: el interés se calcula con signo negativo (<code>clsRetroactivos.cs:431</code>). ¿Los retroactivos son siempre devoluciones?</li><li>Tramas por importe: el cálculo de los vencimientos 3 y 4 parte del total original y no del anterior (<code>clsComprobanteFactura.cs:1856-1863</code>).</li><li>La &quot;demora&quot; informada al final de la masiva sale negativa (<code>clsFacturacionMasiva.cs:669</code>).</li><li><em>Segunda pasada</em>, posibles bugs adicionales, todos <strong>[VERIFICAR]</strong>: <ul><li><strong>Numeración y autorización</strong>: <ul><li>Búsqueda de CAEA con <code>VTO_CESP &amp;lt;= Hoy</code> (ver §4.4) (<code>clsComprobante.cs:825</code>).</li><li>Firmas electrónicas: <code>VerificarSiUsuarioFirmo</code> no filtra por tipo de documento (<code>clsComprobante.cs:277-441</code>).</li></ul></li><li><strong>Comprobantes y ventas</strong>: <ul><li><code>AgregarDetalle</code> une líneas de stock por producto y precio, pero después busca la línea solo por producto (<code>clsComprobanteBase.cs:165-190</code>).</li><li><code>GetItCompV</code>: con descuento, el IVA se calcula sobre el neto sin descuento (<code>clsComprobanteVenta.cs:1361</code>).</li><li><code>GetPAGOS360_1M</code>: la condición <code>CODIGO_BARRA3 != &quot;&quot; || != null</code> siempre es verdadera; la versión para talones ignora el estado (<code>clsFacturasImpresion.cs:2775-2793</code>).</li></ul></li><li><strong>Rendición de fletes</strong> (<code>clsComprobanteRendicion.cs:57-106</code>): <ul><li>Los valores <code>TipoTransporte.SinAsignar</code> y <code>Propio</code> del enum valen ambos 0.</li><li>El &quot;precio por km del viaje&quot; es en realidad precio / viajes.</li></ul></li><li><strong>Exportadores e importaciones</strong>: <ul><li>ENARGAS FDU: el mensaje &quot;categoría no encontrada&quot; usa el marcador {4} con solo 4 argumentos y lanza <code>FormatException</code> (<code>clsEnargas.cs:851-</code>).</li><li>ENARGAS SICC: las filas &quot;F&quot; no excluyen anuladas ni internas, y las filas &quot;C&quot; informan el total de la factura, no lo cobrado (<code>clsEnargas2.cs:1731-1810</code>).</li><li>Importación EME: con cantidad 0 divide por cero, y calcula un cruce por DNI que no usa (<code>clsFacturacionCuotasTerceros.cs:423-490</code>).</li><li>FEDECOBA: el contador de registros no se reinicia entre archivos.</li></ul></li><li><strong>Orden de ítems</strong>: <code>clsItemsOrd.ActualizarOrden</code> asigna orden + ajuste en vez del orden del vecino, lo que puede generar huecos o duplicados (<code>clsItemsOrd.cs:8</code>).</li><li><strong>Informes de facturación</strong> (<code>clsInformes_Facturacion.cs</code>): <ul><li><code>Get_Cuotas_Facturadas_Pendientes</code> (<code>:1416-1575</code>): <ul><li>compara el <code>TIPO</code> de la factura con el número de <code>TipoFecha</code>;</li><li><code>SinActivos</code> repite <code>CONDICION == 2 || == 2</code>;</li><li><code>ConActivos</code> se aplica a la consulta equivocada;</li><li><code>SoloBaja</code> mira solo el primer servicio.</li></ul></li><li><code>Get_ComprobantesNoFacturados</code>: el IVA del interés usa el factor del neto y la cuenta es con <code>float</code> (<code>:170-296</code>).</li><li><code>Get_VentasProductos</code> (<code>:3080</code>, <code>:3108</code>): <ul><li>el filtro de sucursal compara contra <code>COD_COM</code>;</li><li>en créditos el IVA queda <code>−IVA1 + IVA2 + IVA3</code> (solo IVA1 cambia de signo).</li></ul></li><li><code>Get_ConceptosXFactura</code>: con &quot;filtrar por domicilio del servicio&quot; referencia <code>SERSOC.ZON_LEC</code> fuera del <code>outer apply</code>, lo que hace fallar el SQL. Además arma las fechas con <code>ToShortDateString</code>, que depende de la configuración regional (<code>:2033-2036</code>, <code>:2020</code>).</li><li>SQL concatenado con valores de filtro, con riesgo de inyección: <code>GetZonas</code> (<code>clsMovimientoConceptos.cs:2499</code>) y <code>InformeEPRE</code>, aunque este solo usa nombres fijos.</li><li><code>getComprobantes_Bloqueados</code>: <strong>desbloquea como efecto lateral</strong> las facturas pagas al listar (<code>:1326</code>).</li></ul></li><li><strong>Movimiento de conceptos</strong>: la apertura de cuotas por producto prorratea la cantidad sobre <code>NETO</code> y el importe sobre <code>SUBNETO</code>, con aritmética <code>float</code> (<code>clsMovimientoConceptos.cs:673-676</code>).</li><li><strong>Facturas de farmacia</strong>: asume que los códigos de producto de medicamentos y perfumería son consecutivos (base, +1, +2) (<code>clsFacturacionCuotasTerceros.cs:1321-</code>).</li><li><strong>Banco de Córdoba 43</strong>: el importe de 6 dígitos tope; ver 12.4.1.</li></ul></li></ul></li><li><strong>Corridas parciales</strong>: si un lote falla, ¿cómo se recupera hoy? ¿Se vuelve a correr la masiva completa confiando en <code>ULT_FAC</code> para no duplicar?</li><li><strong>Fechas dinámicas</strong>: la sintaxis de <code>Nucleo.GetFechaDinamica</code> (expresiones guardadas en <code>TIPO_FAC.VTO1..4</code>) no está en estas clases; relevarla en <code>CapaNucleo</code>.</li><li><strong>Variables obligatorias</strong> 307, 311, 543, 607, 2247: confirmar su significado en el catálogo (doc 09). <ul><li><em>Respuesta (segunda pasada)</em>: según los textos de validación y su uso: <ul><li>307: concepto de interés por mora.</li><li>311: concepto de interés anterior.</li><li>543: código de <code>IMPUESTO</code> para el IVA.</li><li>607: concepto de interés por financiación.</li><li>2089: concepto de interés del comprobante de venta.</li><li>2247: concepto de descuento en venta contado o 1 cuota.</li></ul></li><li>Sus valores dependen de cada base <strong>[VERIFICAR]</strong>.</li></ul></li><li><strong>Secuencia</strong>: la condición de refacturación por secuencia (<code>clsFacturacionMasiva.cs:1801</code>) permite volver a facturar el mismo período con cualquier secuencia ≠ 0; ¿qué uso real tiene (bimestral, refacturaciones, servicios quincenales)?</li><li><strong>Grupos de factura</strong>: ¿cuántas cooperativas usan más de un grupo (facturas separadas por servicio) y <code>FORZAR_ND</code>?</li><li><strong>Formatos de código de barras en uso</strong>: hay ~100; relevar cuáles usan las cooperativas objetivo de GoodApps para priorizar.</li><li><strong>ENARGAS</strong>: qué protocolo (SARI vs. FCU-DS) está vigente hoy y para qué distribuidoras.</li><li><strong>Cuentas de control</strong>: el tipo &quot;Cuentas_Control&quot; se trata igual que &quot;Varias cuentas&quot; en la selección; ¿la diferencia es solo de UI o de permisos?</li><li><strong>Pagos360</strong>: el significado exacto de los estados de solicitud (0, 1, 4 y el resto) debe confirmarse con el doc 05.</li></ol>`,230)])])}const g=o(t,[["render",r]]);export{m as __pageData,g as default};
